-- ============================================================
-- 0019_dream_items_enrich_a — 꿈 사전 A 묶음 본문 보강 + 길흉 재판정
-- 대상 157건 (본문 2문장 이하 · 요약이 본문 앞부분을 잘라 넣은 것 · 요약이 본문에 그대로 반복된 것).
-- - description 157건 다시 씀, preview 139건(크롤링) 새로 씀
-- - is_lucky 19건, luck_index 11건 변경 (길몽·흉몽 태그 동시 항목 재판정 + 순화 해제 2건)
-- - tags 20건 정리: 길몽 판정 → 흉몽 태그 제거 / 보통 → 길몽·흉몽 제거 / 흉몽 → 길몽 제거,
--   body-033 길몽 추가, crawled-008·110·083 태몽 제거 (지금 배포된 앱 규칙에서도 배지가 맞도록)
-- - 현재 배포된 앱 기준으로 배지가 바뀌는 항목: 19건
-- 
-- 적용 방법: Supabase SQL Editor 에 통째로 붙여 한 번에 실행. 파일 전체가 do 블록 하나(= SQL 문 하나)라
-- Editor 가 문장을 나눠 자동 커밋으로 실행하더라도 원자적이다. 중간에 실패하면 백업까지 포함해 아무것도 바뀌지 않는다.
-- 임시 테이블을 쓰지 않는다 — 문장마다 자동 커밋되면 on commit drop 임시 테이블이 만들자마자 사라져
-- 42P01(relation does not exist)이 난다. 새 값은 아래 JSON 하나로 들고 jsonb_to_recordset 으로 읽는다.
-- 적용 전 supabase/scripts/0019_precheck.sql 로 변경 행 수 확인.
-- 되돌리기: supabase/scripts/0019_rollback.sql (아래에서 만드는 backup.dream_items_0019 에서 복구).
-- 멱등성: 다시 실행해도 같은 값으로 덮어쓴다. 백업은 첫 실행 때 값만 보존(on conflict do nothing).
-- 생성: node supabase/seeds/enrich/a/build-migration.mjs (원본 데이터: supabase/seeds/enrich/a/*.json — 직접 수정하지 말 것)
-- ============================================================

do $mig$
declare
  -- 새 값. null = 그 컬럼은 그대로 둔다.
  src jsonb := $data$
[
{"id":"animal-001","preview":null,"description":"품 안으로 무언가가 달려들어 안기는 꿈은 바깥에 있던 복이 자기 몫으로 들어오는 것을 상징한다. 돼지는 예로부터 넉넉함과 다산을 뜻했고, 한자 '돈(豚)'의 소리가 돈과 같아 살림의 풍요와 흔히 연결되어 왔다. 돼지가 스스로 달려와 안기고 반가운 마음이 컸다면 애쓴 것 이상으로 운이 따른다는 뜻으로 풀이된다. 안긴 돼지가 유난히 크고 묵직했다면 그만큼 넉넉한 복이 오래 머문다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"body-015","preview":null,"description":"몸이 점점 작아지는 꿈은 주변에서 자기 자리가 좁아지고 목소리가 묻히는 상황을 상징한다. 몸집은 그 사람이 지닌 힘과 존재감을 뜻하기 때문에, 이것이 줄어드는 장면은 영향력이 약해지는 것으로 풀이된다. 작아진 몸으로 사람들 사이에 섞여 아무도 알아보지 못했다면 인정받지 못해 서운한 일을 겪을 수 있으니 조심하라는 뜻이다. 작아진 몸으로도 좁은 틈을 빠져나갔다면 몸을 낮추어 어려움을 피해 가는 지혜가 필요하다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"body-031","preview":null,"description":"머리카락을 양쪽으로 가르는 꿈은 하나로 모여 있던 것이 둘로 나뉘는 상황, 곧 집안의 화합이 흔들리는 것을 상징한다. 머리카락은 예로부터 몸의 기운과 가족의 건강에 이어진다고 여겨져, 이를 가르는 행위가 근심의 징조로 풀이된다. 가르는 동안 머리카락이 엉키거나 한 움큼씩 빠졌다면 근심이 쉽게 가시지 않을 수 있다는 뜻이다. 반면 가르마가 깔끔하게 정돈되어 마음이 편안했다면 걱정거리가 크게 번지지 않고 정리된다는 뜻으로 해석되기도 한다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"body-032","preview":null,"description":"억지로 머리카락이 잘려 나가는 꿈은 자기 뜻과 상관없이 소중한 것을 빼앗기는 상황을 상징한다. 머리카락은 예로부터 몸의 기운과 운세를 담는다고 여겨져, 원치 않게 잘리는 것은 기운이 꺾이고 일이 막히는 징조로 풀이된다. 자르는 사람이 낯선 이였다면 바깥 사람 때문에 손해를 볼 수 있으니 거래나 약속을 조심하라는 뜻이다. 잘린 머리카락이 바닥에 수북이 쌓였다면 근심이 한동안 이어질 수 있다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"body-033","preview":null,"description":"머리카락을 한데 모아 묶는 꿈은 흩어져 있던 인연이나 일이 하나로 맺어지는 것을 상징한다. 머리를 올려 묶는 것은 예로부터 혼례나 새 출발을 앞두고 몸가짐을 가다듬는 일과 이어져, 관계가 매듭지어지는 의미로 풀이된다. 묶은 머리가 단정하고 마음에 들었다면 새로 만난 사람과의 관계가 순조롭게 이어진다는 뜻이다. 묶으려 해도 자꾸 풀려 버렸다면 관계를 맺기까지 시간이 조금 더 걸릴 수 있다는 뜻으로 해석된다.","tags":["길몽"],"is_lucky":null,"luck_index":null},
{"id":"body-034","preview":null,"description":"스스로 가위를 들어 머리카락을 자르는 꿈은 묵은 것을 직접 정리하고 새 출발을 준비하는 마음을 상징한다. 머리카락은 쌓여 온 시간과 미련을 뜻하기도 해, 그것을 제 손으로 잘라 내는 것은 마음의 짐을 덜어 내는 것으로 풀이된다. 자르고 난 뒤 거울 속 모습이 마음에 들었다면 바라던 일이 뜻대로 풀린다는 뜻이다. 잘라 낸 머리카락을 미련 없이 쓸어 버렸다면 오래 끌던 문제를 깨끗이 매듭짓게 된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"body-035","preview":null,"description":"머리카락이 한꺼번에 빠져 머리가 휑해지는 꿈은 자신을 지켜 주던 울타리가 갑자기 사라지는 상황을 상징한다. 머리카락은 체면과 기운을 뜻하는데, 그것을 한순간에 잃는 것은 평판과 살림이 크게 흔들리는 징조로 풀이된다. 빠진 머리카락을 붙잡고 당황했다면 주변의 말 한마디에 억울한 누명을 쓸 수 있으니 말과 행동을 조심하라는 뜻이다. 사람들 앞에서 맨머리가 드러나 부끄러웠다면 체면이 상하는 일이 생길 수 있다는 경고로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"body-036","preview":null,"description":"머리카락이 길게 자라나는 꿈은 꾸준히 쌓아 온 힘이 겉으로 드러나며 뻗어 나가는 것을 상징한다. 머리카락은 기운과 생명력을 뜻해, 그것이 길어지는 모습은 하는 일의 흐름이 이어지고 넓어지는 것으로 풀이된다. 길어진 머리카락이 윤기 있고 가지런했다면 주변의 신뢰를 얻어 일이 순조롭게 커 간다는 뜻이다. 누군가 길어진 머리를 빗겨 주었다면 곁에서 힘을 보태 줄 사람이 나타난다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"body-037","preview":null,"description":"머리카락이 곱고 윤기가 흐르는 꿈은 그동안의 노력이 밖으로 빛을 내는 시기를 상징한다. 윤기 있는 머리카락은 기운이 넘치고 몸가짐이 단정한 상태를 뜻해, 남들 눈에 좋은 모습으로 비치는 것으로 풀이된다. 사람들이 머리카락을 보고 감탄했다면 주변에서 자신을 높이 평가하는 일이 생긴다는 뜻이다. 거울 앞에서 스스로 만족스러웠다면 자신감을 얻어 맡은 일을 당당히 해낸다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"body-038","preview":null,"description":"머리카락이 하얗게 세는 꿈은 오랜 경험이 쌓여 무게와 연륜을 갖추게 되는 것을 상징한다. 흰머리는 나이 듦과 함께 지혜와 존경을 뜻해, 그것이 나타나는 장면은 사람들 사이에서 위치가 단단해지는 것으로 풀이된다. 흰머리가 은빛으로 곱게 빛났다면 마음의 짐을 덜고 편안한 시기를 맞는다는 뜻이다. 흰머리가 된 자신을 보며 담담했다면 건강하게 오래 복을 누린다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"body-039","preview":null,"description":"바람에 머리카락이 마구 흩날리는 꿈은 마음을 붙잡아 줄 중심이 흔들리는 상황을 상징한다. 정돈되어야 할 머리카락이 바람에 엉키는 모습은 생각이 갈피를 잡지 못하고 집안 분위기도 어수선해지는 것으로 풀이된다. 흩날리는 머리카락 때문에 앞이 보이지 않았다면 판단이 흐려져 일을 그르칠 수 있으니 큰 결정은 조심하라는 뜻이다. 바람이 잦아들며 머리카락이 가라앉았다면 어수선한 시기가 오래가지 않는다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-001","preview":"큰 변화가 닥쳐 삶의 방향이 달라지는 꿈","description":"땅이 갈라지는 꿈은 발 딛고 선 생활의 기반이 뿌리째 흔들리는 시기를 상징한다. 땅은 터전과 안정을 뜻해, 그것이 갈라진다는 것은 익숙하던 질서가 깨지고 새로운 국면이 열린다는 의미로 풀이된다. 갈라진 틈 사이로 새싹이나 맑은 물줄기가 보였다면 혼란 끝에 새로운 길이 열린다는 뜻으로 해석된다. 다만 갈라지는 땅 앞에서 두려움이 컸다면 뜻밖의 사고에 휘말릴 수 있으니 몸과 주변을 조심하라는 뜻으로 본다.","tags":["조건부"],"is_lucky":"conditional","luck_index":50},
{"id":"crawled-002","preview":"살림의 터전과 집안 여성에게 근심이 드는 흉몽","description":"땅이 꺼지는 꿈은 기대고 있던 재산이나 생활의 기반이 무너지는 것을 상징한다. 땅은 재산과 생활터전, 집안의 여성을 뜻한다고 여겨져, 발밑이 내려앉는 모습이 그 터전을 잃거나 어머니·아내 같은 이에게 안 좋은 일이 생기는 것으로 풀이된다. 꺼진 땅에 함께 빠져들었다면 그 손실이 자신에게 직접 미칠 수 있으니 큰 거래나 보증은 피하는 것이 좋다. 멀리서 땅이 꺼지는 것을 바라보기만 했다면 주변의 어려움을 미리 알아차리고 대비할 시간이 있다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-003","preview":"가족 전체에 큰 변화가 한꺼번에 찾아오는 꿈","description":"이빨이 몽땅 빠지는 꿈은 집안을 이루던 관계가 한 번에 바뀌는 시기를 상징한다. 이빨 하나하나가 가족 구성원과 이어진다고 여겨져, 한꺼번에 빠진다는 것은 집안 전체가 같은 흐름을 탄다는 의미로 풀이된다. 빠진 자리에 새 이가 돋는 느낌이 들었다면 묵은 걱정이 정리되고 식구들이 새 출발을 한다는 뜻으로 해석된다. 다만 빠지는 동안 몹시 아프고 불안했다면 가까운 사람에게 어려운 일이 생길 수 있으니 안부를 살피라는 뜻으로 본다.","tags":["조건부"],"is_lucky":"conditional","luck_index":50},
{"id":"crawled-004","preview":"낯선 분야에 뛰어들어 좋은 성과를 거두는 길몽","description":"땅을 사들이는 꿈은 자기 이름으로 된 새로운 터전을 마련하고 일을 시작하는 것을 상징한다. 땅은 무언가를 심고 가꾸어 거둘 수 있는 바탕이라, 그것을 손에 넣는 것은 앞으로 키워 갈 일의 기반을 얻는 것으로 풀이된다. 넓고 기름진 땅을 샀다면 시작한 일이 크게 자라 오래도록 수확을 안겨 준다는 뜻이다. 땅문서를 받아 들고 뿌듯했다면 노력한 만큼 확실한 결과를 손에 쥐게 된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-005","preview":"일터와 집안에 사고와 근심이 깃드는 흉몽","description":"땅 위에 드러나 있던 지렁이가 모습을 감추는 꿈은 눈앞에 보이던 기회나 살림의 힘이 손에서 빠져나가는 것을 상징한다. 지렁이는 흙을 일구어 땅을 기름지게 하는 존재로 여겨져, 그것이 땅속으로 숨는다는 것은 생계를 받쳐 주던 힘이 약해지는 것으로 풀이된다. 지렁이를 붙잡으려다 놓쳤다면 다 된 일이 막판에 어긋날 수 있으니 계약이나 약속을 한 번 더 확인하는 것이 좋다. 지렁이가 숨는 것을 담담히 지켜보았다면 걱정거리가 생기더라도 크게 번지지 않고 지나간다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-006","preview":"큰 분란과 다툼에 휘말릴 수 있음을 알리는 흉몽","description":"땅이 몹시 흔들리는 꿈은 주변을 크게 뒤흔드는 사건이 일어나는 것을 상징한다. 땅은 모두가 딛고 선 질서를 뜻해, 그것이 흔들린다는 것은 많은 사람이 얽힌 갈등이나 변동이 터져 나오는 것으로 풀이된다. 개인적으로는 작은 오해가 커져 시비나 송사에 얽힐 수 있으니 말과 서류를 조심하라는 뜻이다. 흔들림 속에서 건물이 무너지는 것을 보았다면 믿고 있던 일이나 자리에 변동이 생길 수 있다는 경고로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-007","preview":"예술적 재능이 빼어난 아이를 얻는 길몽","description":"땅에 떨어진 금붕어를 주워 어항에 넣어 주는 꿈은 귀한 생명을 정성껏 받아 품는 것을 상징하는 태몽으로 전해진다. 금붕어는 화려한 빛깔과 유려한 움직임 때문에 아름다움과 재주를 뜻하고, 그것을 물속으로 돌려보내는 것은 그 재주가 제자리를 찾아 꽃피는 것으로 풀이된다. 어항 속 금붕어가 힘차게 헤엄쳤다면 아이가 건강하게 자라 솜씨를 마음껏 펼친다는 뜻이다. 금붕어의 빛깔이 유난히 선명했다면 남다른 감각으로 사람들의 눈길을 끄는 아이가 된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-008","preview":"인물은 빼어나지만 평범하게 살 아이를 알리는 꿈","description":"용이 하늘에 오르지 못하고 땅에 머무는 꿈은 뛰어난 바탕을 지녔지만 그 기운을 다 펼치지 못하는 삶을 상징한다. 용은 하늘로 올라야 비로소 큰 힘을 얻는 존재로 여겨져, 땅에 내려앉은 용은 재주에 비해 세력이나 높은 지위와는 인연이 닿지 않는다는 의미로 풀이된다. 태몽이라면 생김새와 됨됨이가 남다른 아이를 얻되, 큰 이름을 떨치기보다 제자리에서 무난한 삶을 꾸린다는 뜻으로 해석된다. 땅에 있는 용의 눈빛이 맑고 몸에 윤기가 돌았다면 이름은 크게 나지 않아도 건강하고 바르게 자란다는 뜻으로 본다.","tags":[],"is_lucky":"neutral","luck_index":50},
{"id":"crawled-009","preview":"공들인 일이 뒤늦은 후회로 돌아오는 흉몽","description":"연못을 만들려고 땅을 파는 꿈은 공을 들여 무언가를 꾸미지만 그 결과가 기대와 다르게 흘러가는 상황을 상징한다. 물을 담으려 땅을 깊이 파헤치는 것은 멀쩡한 바탕을 허물어 가며 일을 벌이는 것으로 여겨져, 애쓴 만큼 아쉬움이 남는 일로 풀이된다. 파 놓은 구덩이에 물이 고이지 않았다면 들인 돈이나 시간이 헛되이 될 수 있으니 무리한 투자를 조심하라는 뜻이다. 땅을 파다 손을 다쳤다면 서두르다 일이 어긋나 마음고생을 할 수 있다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-010","preview":"숨겨야 할 일을 조용히 매듭짓게 되는 꿈","description":"자신이 죽인 시체를 땅에 묻는 꿈은 끝난 일을 정리하고 남들 눈에 드러나지 않게 덮어 두려는 마음을 상징한다. 꿈에서 죽음은 어떤 일의 마무리를, 땅에 묻는 것은 그것을 보이지 않는 곳에 갈무리하는 것을 뜻해, 처리한 일을 비밀로 지켜야 하는 처지로 풀이된다. 흙을 꼼꼼히 덮고 마음이 후련했다면 미뤄 둔 일을 깔끔하게 끝맺게 된다는 뜻이다. 누군가 지켜보는 것 같아 불안했다면 감춘 일이 드러날까 마음 졸일 수 있으니 처음부터 정직하게 처리하라는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-011","preview":"떳떳하지 못한 일에 휘말릴 수 있다는 흉몽","description":"땅속을 물속처럼 헤엄쳐 다니는 꿈은 남의 눈을 피해 드러나지 않는 길로 움직이는 상황을 상징한다. 땅속은 본래 사람이 다닐 수 없는 곳이라, 그곳을 헤엄친다는 것은 정해진 규칙을 벗어나 은밀하게 일을 꾸미는 것으로 풀이된다. 헤엄치다 숨이 막혀 괴로웠다면 무리하게 벌인 일이 들통나 곤란을 겪을 수 있으니 조심하라는 뜻이다. 누군가에게 쫓기며 땅속을 헤엄쳤다면 윗사람이나 기관과 맞서게 되어 구설에 오를 수 있다는 경고로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-012","preview":"추진하는 일이 많은 사람의 마음을 움직이는 길몽","description":"번개 같은 빛줄기가 하늘에서 땅으로 곧게 내리꽂히는 꿈은 위에서 받은 큰 힘이 지금 하는 일에 닿는 것을 상징한다. 하늘의 빛은 영감과 계시를 뜻하고 그것이 땅에 닿는 것은 생각이 현실로 이루어지는 것으로 여겨져, 해 온 일이 널리 알려지고 인정받는 것으로 풀이된다. 빛줄기가 자신을 비추었다면 사람들의 눈길이 자신에게 모여 뜻밖의 기회를 얻는다는 뜻이다. 빛이 닿은 땅에서 새싹이 돋거나 환해졌다면 시작한 일이 좋은 결실로 이어진다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-013","preview":"연구와 창작이 결실을 맺어 세상에 나오는 길몽","description":"수많은 별이 하늘에서 쏟아져 땅에 쌓이는 꿈은 손에 쥘 수 있는 귀한 것이 한꺼번에 모여드는 것을 상징한다. 별은 지식과 영감, 빛나는 성과를 뜻해, 그것이 땅에 수북이 쌓이는 모습은 모아 온 생각과 자료가 형태를 갖추는 것으로 풀이된다. 쌓인 별을 두 손 가득 주워 담았다면 그동안 쏟은 노력이 작품이나 성과로 드러나 인정받는다는 뜻이다. 별 무더기가 밤새 환하게 빛났다면 그 성과가 오래도록 사람들에게 기억된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-014","preview":"사소한 일로 다툼과 걱정이 생기는 흉몽","description":"땅에서 동전 몇 개를 줍는 꿈은 하찮은 이득에 마음을 쓰다 더 큰 것을 놓치는 상황을 상징한다. 동전은 작은 돈이자 자잘한 일을 뜻해, 그것을 몇 개 줍는 것은 대수롭지 않은 문제로 신경이 곤두서는 것으로 풀이된다. 동전을 두고 누군가와 실랑이를 벌였다면 가까운 사람과 언쟁으로 감정이 상할 수 있으니 말을 아끼라는 뜻이다. 주운 동전이 녹슬거나 더러웠다면 생각지 않은 지출로 근심할 수 있다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-015","preview":"바라던 일이 뜻대로 풀리지 않음을 알리는 흉몽","description":"급히 화장실을 찾았지만 마땅한 곳이 없어 들어가지 못하는 꿈은 해결해야 할 일을 앞두고 길이 막힌 답답한 상황을 상징한다. 꿈에서 화장실은 쌓인 것을 비워 내고 일을 마무리하는 곳이라, 그곳에 들어가지 못한다는 것은 처리해야 할 일이 미뤄지는 것으로 풀이된다. 문이 모두 잠겨 있거나 줄이 길어 애를 태웠다면 남의 사정 때문에 일이 지연되어 손해를 볼 수 있으니 미리 대비하라는 뜻이다. 화장실이 지저분해 돌아섰다면 내키지 않는 조건 때문에 기회를 포기하게 될 수 있다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-016","preview":"재산이 불어나고 저축이 넉넉해지는 길몽","description":"스스로 땅을 파고 몸을 묻는 꿈은 땅이 지닌 기운 속에 자신을 깊이 들여놓는 것을 상징한다. 땅은 재물과 터전을 뜻해, 그 속에 몸이 잠기는 것은 재물에 둘러싸이고 살림이 단단해지는 것으로 풀이된다. 흙이 따뜻하고 포근하게 느껴졌다면 모아 둔 돈이 안정적으로 늘어 마음이 든든해진다는 뜻이다. 몸을 묻은 자리에서 싹이 돋았다면 작은 투자가 오랜 시간에 걸쳐 큰 몫으로 돌아온다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-017","preview":"자신과 주변에 불길한 일이 닥칠 징조인 흉몽","description":"갈라진 땅 틈으로 몸이 빠져드는 꿈은 믿고 서 있던 자리가 꺼지며 발 디딜 곳을 잃는 상황을 상징한다. 땅은 삶을 받치는 바탕을 뜻해, 그 틈에 빠진다는 것은 예상치 못한 사고나 낭패에 휘말리는 것으로 풀이된다. 빠지면서 손을 뻗어도 잡을 것이 없었다면 도움받기 어려운 처지에 놓일 수 있으니 큰일을 앞두고 조심하라는 뜻이다. 가족이나 지인이 함께 빠졌다면 가까운 사람에게 근심스러운 일이 생길 수 있다는 경고로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-018","preview":"새 집이나 새 직장을 얻고 재산이 느는 길몽","description":"자신을 묻으려고 땅을 파는 꿈은 지금까지의 자리를 정리하고 새로 뿌리내릴 곳을 마련하는 것을 상징한다. 땅을 판다는 것은 터를 닦는 일이고 그 속에 들어간다는 것은 그곳에 자리를 잡는 것을 뜻해, 머물 곳이나 일할 곳이 새로 생기는 것으로 풀이된다. 구덩이를 힘들이지 않고 쉽게 팠다면 이사나 이직이 순조롭게 진행된다는 뜻이다. 파낸 흙이 기름지고 검었다면 새로 잡은 터전에서 살림이 넉넉해진다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-019","preview":"재물이 묶이고 곤란과 불안이 찾아오는 흉몽","description":"땅속에 파묻히는 꿈은 움직일 틈 없이 무언가에 짓눌려 갇히는 상황을 상징한다. 흙에 덮인다는 것은 가진 것이 땅속에 묻혀 쓸 수 없게 되는 것과 이어져, 돈이 돌지 않고 일이 막히는 것으로 풀이된다. 숨이 막혀 버둥거렸다면 빚이나 책임에 쫓겨 마음고생을 할 수 있으니 무리한 약속을 피하라는 뜻이다. 누군가 흙을 덮고 있었다면 주변 사람 때문에 손해를 볼 수 있다는 경고로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-020","preview":"생활이 안정되고 반가운 대접을 받는 길몽","description":"땅바닥에 편히 앉아 있는 꿈은 떠돌던 마음을 내려놓고 한곳에 자리를 잡는 것을 상징한다. 땅에 몸을 붙이고 앉는다는 것은 기반에 단단히 닿아 있다는 뜻이라, 살림과 주변 환경이 차분히 자리 잡는 것으로 풀이된다. 여럿이 둘러앉아 웃으며 이야기를 나눴다면 정다운 사람들과 어울리며 음식이나 술을 얻어먹을 일이 생긴다는 뜻이다. 따뜻한 볕이 드는 곳에 앉아 있었다면 한동안 걱정 없이 편안한 나날이 이어진다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-021","preview":"부동산과 권력, 명성이 따르고 재복이 드는 길몽","description":"몸이 땅속으로 빨려 들어가는 꿈은 땅이 품은 기운이 자신에게 스며들어 하나가 되는 것을 상징한다. 땅은 재산과 영토, 세력을 뜻해, 그 속으로 깊이 들어간다는 것은 그것들을 자기 것으로 끌어안는 것으로 풀이된다. 빨려 들어가면서도 겁나지 않고 편안했다면 집이나 땅처럼 오래 남는 재산을 얻게 된다는 뜻이다. 땅속에서 넓은 공간이 펼쳐졌다면 맡는 일의 범위가 넓어지고 이름이 알려진다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-022","preview":"남의 것을 따라 하다 체면을 잃을 수 있는 흉몽","description":"다 익어 땅에 떨어진 감을 주워 먹는 꿈은 남이 거두고 남긴 것에 손을 대는 상황을 상징한다. 떨어진 감은 제때 거두지 못하고 버려진 것을 뜻해, 그것을 주워 먹는 모습은 스스로 일구지 않은 것을 탐내는 것으로 풀이된다. 감을 줍는 모습을 사람들이 지켜보고 있었다면 남들 앞에서 웃음거리가 되거나 업신여김을 받을 수 있으니 조심하라는 뜻이다. 주운 감이 물러 터지거나 떫었다면 남의 방식을 흉내 낸 일이 기대에 못 미쳐 망신을 살 수 있다는 경고로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-023","preview":"형편이 트이고 일터에서 자리가 높아지는 길몽","description":"땅을 팔아 돈을 버는 꿈은 묶여 있던 자산이 움직이며 새로운 기회로 바뀌는 것을 상징한다. 땅은 쉽게 움직이지 않는 기반을 뜻하는데, 그것을 넘기고 손에 돈을 쥔다는 것은 오래 기다리던 변화가 실제 소득으로 이어진다는 의미로 풀이된다. 값을 잘 받고 흡족했다면 일을 찾던 사람은 일할 곳을 얻고, 일하던 사람은 더 중요한 일을 맡게 된다는 뜻이다. 다만 몸이 약한 이가 꾼 꿈이라면 무리하지 말고 건강부터 챙기라는 뜻으로 보기도 한다.","tags":["조건부","길몽"],"is_lucky":"lucky","luck_index":75},
{"id":"crawled-024","preview":"주도권을 잡고 세력을 넓혀 가는 길몽","description":"땅속에 묻힌 옥새를 파내는 꿈은 감춰져 있던 권한과 자격을 자기 손으로 찾아내는 것을 상징한다. 옥새는 나라를 다스리는 권위의 증표라, 그것을 얻는다는 것은 일을 이끄는 자리에 올라 결정권을 갖게 되는 것으로 풀이된다. 옥새가 흙 속에서도 빛을 잃지 않고 반짝였다면 오래 묵혀 둔 능력이 인정받아 중요한 일을 맡게 된다는 뜻이다. 파낸 옥새를 사람들 앞에 내보였다면 따르는 사람이 늘고 영향력이 커진다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-025","preview":"지위가 흔들리고 시험과 연애에 실패하는 흉몽","description":"평평한 맨땅에서 미끄러져 넘어지는 꿈은 방심한 사이에 발판을 잃고 체면이 구겨지는 상황을 상징한다. 아무 장애물 없는 땅에서 넘어진다는 것은 쉬워 보이던 일에서 뜻밖의 실수를 하는 것으로 여겨져, 자리나 평판이 낮아지는 징조로 풀이된다. 넘어지는 모습을 여러 사람이 보았다면 실수가 알려져 구설에 오를 수 있으니 말과 행동을 조심하라는 뜻이다. 넘어진 뒤 쉽게 일어나지 못했다면 한 번의 좌절이 연달아 이어질 수 있다는 경고로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-026","preview":"소원이 이루어지고 막힘없이 일이 풀리는 길몽","description":"하늘과 땅이 맞닿아 하나로 합쳐지는 꿈은 서로 떨어져 있던 뜻과 현실이 만나 완전해지는 것을 상징한다. 하늘은 바람과 이상을, 땅은 현실과 터전을 뜻해, 둘이 합쳐지는 것은 마음먹은 일이 그대로 현실이 되는 것으로 풀이된다. 합쳐지는 순간 주변이 환하게 밝아졌다면 오랫동안 바라던 일이 한꺼번에 해결된다는 뜻이다. 그 광경을 경건한 마음으로 바라보았다면 하는 일마다 순서대로 맞아떨어져 걸림돌이 사라진다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-027","preview":"우울한 일과 근심거리가 생길 수 있는 흉몽","description":"땅에 엎드려 있는 꿈은 몸과 마음을 일으키지 못하고 낮게 웅크린 상태를 상징한다. 땅에 바짝 엎드린다는 것은 기운이 꺾여 고개를 들지 못하는 모습과 이어져, 마음이 가라앉고 걱정에 눌리는 것으로 풀이된다. 엎드린 채 울고 있었다면 쌓인 서운함이 터져 나올 수 있으니 혼자 끙끙 앓지 말고 가까운 사람에게 털어놓으라는 뜻이다. 누군가에게 억지로 엎드리게 되었다면 윗사람이나 상대에게 굽혀야 하는 일이 생겨 자존심이 상할 수 있다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-028","preview":"주위의 간계로 사업과 체면이 기우는 흉몽","description":"땅에 구덩이를 파고 그 안에 몸을 숨겨 위장하는 꿈은 정면으로 나서지 못하고 숨어서 상황을 엿보는 처지를 상징한다. 구덩이와 위장은 속임수와 함정을 뜻해, 자신이나 주변 사람이 꾀를 부리며 서로를 경계하는 관계로 풀이된다. 위장이 들킬까 조마조마했다면 주변의 간사한 말에 휘둘려 하는 일이 점점 부실해질 수 있으니 조심하라는 뜻이다. 구덩이 밖에서 누군가 웃고 있었다면 믿었던 사람에게 이용당해 자존심이 크게 상할 수 있다는 경고로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-029","preview":"새 일에 활기가 돌고 학문에 깊이 몰두하는 길몽","description":"땅이 갈라진 틈을 내려다보는 꿈은 겉으로 드러나지 않던 속을 들여다보며 새로운 길을 발견하는 것을 상징한다. 갈라진 땅은 굳어 있던 것이 열리는 변화를 뜻해, 그 틈을 살핀다는 것은 막혀 있던 일이 움직이기 시작하는 것으로 풀이된다. 틈 사이로 맑은 물이나 빛이 보였다면 시작한 일이 생기를 띠며 기대 이상의 성과로 이어진다는 뜻이다. 두려움 없이 오래 들여다보았다면 한 분야를 파고들어 남다른 실력을 쌓게 된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-030","preview":"오래 품은 목표가 마침내 결실을 맺는 꿈","description":"땅굴 깊은 곳에서 큰 구렁이가 모습을 드러내는 꿈은 숨어 있던 기회가 바깥으로 나타나는 것을 상징한다. 땅굴을 쑤시는 행동은 끈질긴 노력을, 그 끝에 나온 큰 구렁이는 노력에 걸맞은 보상을 뜻해 시험 합격이나 바라던 취직으로 풀이된다. 구렁이가 순순히 굴 밖으로 기어 나왔다면 일이 큰 막힘 없이 풀린다는 뜻이다. 구렁이의 몸집이 유난히 굵고 윤기가 흘렀다면 얻게 될 자리나 성과가 기대보다 크다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-031","preview":"예상 못한 불안과 병치레가 이어지는 흉몽","description":"땅에 바짝 붙어 엎드린 채 낮게 나는 꿈은 마음껏 날아오르지 못하고 짓눌린 처지를 상징한다. 하늘을 나는 꿈은 본래 뜻을 펼치는 것을 뜻하지만, 땅을 스치듯 엎드려 나는 모습은 기운이 꺾이고 몸과 마음이 지쳐 있음을 드러내는 것으로 풀이된다. 날다가 자꾸 땅에 몸이 긁히거나 부딪혔다면 건강을 해치거나 근심이 오래 이어질 수 있으니 조심하라는 뜻이다. 낮게 날면서도 끝내 원하는 곳에 닿았다면 어려움이 길어도 결국 벗어날 수 있다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-032","preview":"새로 시작한 사업이 불길처럼 크게 일어나는 꿈","description":"벼락이 땅에 내리꽂혀 불이 붙는 꿈은 갑작스러운 계기로 새로운 일이 힘차게 시작되는 것을 상징한다. 벼락은 하늘의 강한 기운을, 땅에 붙은 불은 그 기운이 현실에서 타오르며 번지는 것을 뜻해 투자나 새 사업이 좋은 성과로 이어지는 징조로 풀이된다. 불이 크고 밝게 번져 나갔다면 일의 규모가 빠르게 커진다는 뜻이다. 불이 붙은 자리를 두려움 없이 바라보았다면 변화를 기회로 삼아 주도적으로 이끌어 간다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-033","preview":"승진과 합격 같은 경사가 잇따르는 길몽","description":"땅거미가 나무를 타고 위로 기어오르는 꿈은 낮은 자리에서 차근차근 높은 곳으로 올라가는 상승의 흐름을 상징한다. 거미는 꾸준히 줄을 치며 제 터를 넓혀 가는 존재이고, 나무를 오르는 움직임은 지위와 운이 높아지는 것을 뜻해 승진이나 당선 같은 기쁜 일로 풀이된다. 거미가 막힘없이 꼭대기까지 올라갔다면 하던 일이 순조롭게 마무리된다는 뜻이다. 오르는 도중 거미줄을 넓게 펼쳤다면 일과 관계가 함께 넓어져 든든한 기반이 생긴다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-034","preview":"가족과 친척이 뿔뿔이 흩어지게 됨을 알리는 흉몽","description":"집이 서 있던 터가 텅 빈 들판으로 바뀌는 꿈은 함께 모여 살던 울타리가 사라지는 것을 상징한다. 집터는 한 집안이 뿌리내린 자리이기에, 그곳이 들판이 되었다는 것은 가까운 사람들 사이의 결속이 느슨해지고 각자 떠나게 되는 것으로 풀이된다. 들판 한가운데 홀로 서서 쓸쓸함을 느꼈다면 가족이나 친지와의 왕래가 끊기거나 다툼으로 멀어질 수 있으니 서운한 일을 미리 풀어 두는 것이 좋다. 들판에 새싹이 돋아 있었다면 헤어짐 뒤에 새로운 터전을 꾸리게 된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-035","preview":"작게 시작한 사업이 크게 불어나 번창하는 꿈","description":"갈라진 땅 틈에서 구더기가 끝없이 기어 나오는 꿈은 작은 것이 셀 수 없이 불어나는 번식과 확장을 상징한다. 꿈에서 구더기는 불쾌한 모습과 달리 재물과 사람이 많이 모이는 것을 뜻하는 경우가 많고, 갈라진 땅은 새 판로가 열리는 것을 나타내 생산과 유통에서 큰 이익을 보는 것으로 풀이된다. 구더기가 많을수록 거래처나 손님이 늘어난다는 뜻이다. 구더기를 보고도 징그럽지 않고 담담했다면 기회를 놓치지 않고 일을 키워 간다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-036","preview":"집안에 송사나 오랜 병치레가 생기는 흉몽","description":"거미줄에 죽은 곤충이 잔뜩 얽혀 있는 꿈은 풀리지 않고 엉켜 버린 문제에 붙잡힌 처지를 상징한다. 거미집은 한번 걸리면 빠져나오기 어려운 덫을 뜻하고, 그 안의 죽은 곤충은 기운을 잃고 묶여 있는 사람을 나타내 다툼이 법정까지 가거나 고질병으로 고생하는 것으로 풀이된다. 얽힌 곤충을 떼어 내려다 손에 거미줄이 감겼다면 남의 일에 끼어들었다가 곤란을 겪을 수 있으니 조심해야 한다. 거미줄을 걷어 내고 깨끗이 치웠다면 오래 끌던 문제가 정리될 실마리가 생긴다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-037","preview":"근심이 끊이지 않고 마음이 무거워지는 흉몽","description":"맨땅 위에 그대로 누워 있는 꿈은 기운이 빠져 일어설 힘을 잃은 상태를 상징한다. 땅에 몸을 눕히는 모습은 쉬는 것이 아니라 무거운 짐에 눌려 움직이지 못하는 것으로 여겨져, 걱정거리가 계속 이어지는 것으로 풀이된다. 차갑고 축축한 땅에 누워 몸이 떨렸다면 건강을 해치거나 마음고생이 길어질 수 있으니 무리하지 말라는 뜻이다. 누군가 손을 내밀어 일으켜 주었다면 주변의 도움으로 시름을 덜게 된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-038","preview":"무리한 추진이 실패로 이어질 수 있다는 흉몽","description":"손에 든 지도를 땅에 떨어뜨리는 꿈은 일의 방향과 계획을 놓쳐 버리는 것을 상징한다. 지도는 목적지까지 가는 길과 앞날의 설계를 뜻하기 때문에, 그것을 떨어뜨린다는 것은 준비가 부족한 채 서둘러 나아가다 길을 잃는 것으로 풀이된다. 떨어진 지도가 바람에 날아가거나 흙탕물에 젖었다면 계획이 크게 어긋나 손실을 볼 수 있으니 조심해야 한다. 지도를 곧바로 주워 들고 다시 살펴보았다면 잠시 멈추고 계획을 고치면 낭패를 피할 수 있다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-039","preview":"하는 일마다 크게 이루며 운이 트이는 길몽","description":"땅속에서 대통령의 옥새를 캐내는 꿈은 숨겨져 있던 큰 권한과 명예가 자기 손에 들어오는 것을 상징한다. 옥새는 나라의 가장 높은 권위를 뜻하는 도장이라, 이를 땅에서 찾아낸다는 것은 오랜 노력 끝에 최고의 자리와 성공을 얻는 것으로 풀이된다. 옥새가 흠 없이 빛나고 있었다면 얻게 될 지위나 성과가 오래도록 흔들리지 않는다는 뜻이다. 캐낸 옥새로 직접 도장을 찍었다면 중요한 결정을 스스로 내려 큰일을 성사시킨다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-040","preview":"곤경과 병, 마음의 불안이 찾아오는 흉몽","description":"돌과 가시가 가득한 거친 땅 위에 홀로 우뚝 서 있는 꿈은 기댈 곳 없이 험한 환경에 놓인 처지를 상징한다. 거친 땅은 발을 디딜 때마다 상처를 입는 고단한 현실을 뜻해, 그 위에 서 있다는 것은 어려운 형편과 몸과 마음의 피로가 겹치는 것으로 풀이된다. 서 있는 동안 발이 아프거나 피가 났다면 건강을 해칠 수 있으니 무리한 일정은 피하는 것이 좋다. 멀리 평탄한 길이 보였다면 지금의 어려움이 오래가지 않고 지나간다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-041","preview":"위협에서 벗어나 경쟁에서 이기게 되는 꿈","description":"상대가 들고 있던 권총을 내려놓거나 땅에 떨어뜨리는 꿈은 나를 겨누던 압박이 힘을 잃는 것을 상징한다. 권총은 생사를 가를 만큼 강한 공격을 뜻하기 때문에, 그것이 땅에 떨어진다는 것은 큰 위기에서 놓여나고 맞서던 상대가 물러서는 것으로 풀이된다. 떨어진 권총을 자신이 주워 들었다면 주도권을 쥐고 일을 원하는 방향으로 이끌게 된다는 뜻이다. 상대가 순순히 등을 돌려 떠났다면 다툼이 크게 번지지 않고 원만하게 마무리된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-042","preview":"귀인의 도움으로 큰 재물이 쌓이게 되는 꿈","description":"누군가 쌀을 한가득 가져다주는 꿈은 다른 사람의 손을 거쳐 넉넉한 복이 들어오는 것을 상징한다. 쌀은 예로부터 살림의 바탕이자 넉넉함을 뜻해, 남이 그것을 통째로 건네준다는 것은 주변의 후원을 받아 형편이 크게 나아지는 것으로 풀이된다. 쌀자루가 무거워 겨우 들어 올렸다면 들어오는 몫이 생각보다 크다는 뜻이다. 받은 쌀을 이웃과 나누었다면 얻은 복이 인연으로 이어져 더 오래 간다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-043","preview":"귀하게 될 자손을 잉태하게 되는 태몽의 꿈","description":"하늘과 땅이 서로 맞닿아 하나로 붙는 꿈은 서로 다른 두 기운이 만나 새 생명을 이루는 것을 상징한다. 하늘은 아버지의 기운을, 땅은 어머니의 기운을 뜻한다고 여겨져, 둘이 맞붙는 장면은 귀한 아이를 갖게 되는 징조로 풀이된다. 맞붙는 순간 밝은 빛이 퍼졌다면 태어날 아이의 앞날이 환하고 이름을 널리 알린다는 뜻이다. 그 장면을 두려움 없이 편안하게 바라보았다면 임신과 출산이 순조롭다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-044","preview":"지난날을 돌아보고 바르게 거듭나게 되는 꿈","description":"땅속 깊은 곳에 지옥이 펼쳐져 있는 것을 보는 꿈은 마음 깊이 묻어 둔 잘못과 후회를 마주하는 것을 상징한다. 지옥은 저지른 일의 대가를 치르는 곳으로 여겨져, 이를 내려다보는 것은 자신의 지난 행동을 비추어 보는 거울과 같다고 풀이된다. 지옥의 모습을 보고 크게 뉘우치는 마음이 들었다면 잘못을 바로잡고 한층 성숙해진다는 뜻이다. 지옥에서 누군가를 끌어올려 주었다면 미뤄 둔 사과나 화해를 하게 되어 관계가 회복된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-045","preview":"오랜 노력이 보상받고 일이 순조로워지는 길몽","description":"발밑의 땅이 온통 푸르게 물든 꿈은 메마른 시기가 지나고 생기가 돌아오는 것을 상징한다. 푸른 땅은 풀과 곡식이 잘 자라는 기름진 터를 뜻해, 그동안 들인 수고가 열매를 맺고 하는 일마다 막힘없이 풀리는 것으로 풀이된다. 푸른 들판을 맨발로 걸으며 상쾌함을 느꼈다면 몸과 마음이 함께 건강해진다는 뜻이다. 푸른 땅 위에 꽃이 피어 있었다면 기다리던 기쁜 소식이 함께 찾아온다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-046","preview":"땅과 세력을 넓혀 영향력을 쥐게 되는 꿈","description":"몸이 저절로 땅속으로 스며들 듯 빠져 들어가는 꿈은 어떤 영역에 깊이 뿌리를 내리는 것을 상징한다. 땅은 토지와 터전, 나아가 한 집단의 기반을 뜻하기에, 그 속으로 들어간다는 것은 토지를 얻거나 조직 안에서 확고한 자리를 차지하는 것으로 풀이된다. 빠져 들어가면서도 숨이 편하고 아늑했다면 새 자리에 쉽게 적응해 힘을 키운다는 뜻이다. 땅속에서 넓은 공간이 펼쳐졌다면 앞으로 다스리게 될 영역이 생각보다 크다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-047","preview":"누리던 인기와 명성이 갑자기 꺾이는 흉몽","description":"곱게 피어 있던 분꽃이 땅에 떨어지는 꿈은 화려하던 시기가 끝을 맞는 것을 상징한다. 분꽃은 저녁마다 화사하게 피는 꽃이라 사람들의 관심을 뜻하는데, 그것이 땅에 떨어진다는 것은 쌓아 온 이름이 한순간에 무너지는 것으로 풀이된다. 떨어진 꽃잎이 짓밟혀 있었다면 남의 구설에 오르거나 신뢰를 잃을 수 있으니 말과 행동을 조심해야 한다. 떨어진 꽃을 주워 소중히 간직했다면 화려함은 줄어도 곁에 남는 사람들이 힘이 되어 준다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-048","preview":"뜻밖의 일로 몸과 마음이 편치 않게 되는 흉몽","description":"발밑의 땅이 높고 낮게 울퉁불퉁 솟은 꿈은 앞길이 고르지 못하고 순탄하지 않은 것을 상징한다. 평평해야 할 땅이 들쭉날쭉하다는 것은 예상하지 못한 일이 갑자기 끼어들어 일상이 흔들리는 것으로 풀이된다. 걷다가 비틀거리거나 넘어졌다면 놀랄 일이나 작은 사고가 생길 수 있으니 서두르지 말고 조심하는 것이 좋다. 울퉁불퉁한 길을 끝까지 무사히 지나왔다면 마음고생은 있어도 큰 탈 없이 넘긴다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-049","preview":"이름을 널리 알리며 출세하게 되는 길몽","description":"땅바닥에 자신의 이름 석 자가 또렷이 쓰여 있는 꿈은 세상에 자신의 존재를 새기는 것을 상징한다. 땅에 새겨진 글씨는 많은 사람이 오가며 보게 되는 자리에 남는 표식이라, 사회에 알려지고 공적인 자리에 오르는 것으로 풀이된다. 글씨가 크고 선명할수록 얻게 될 명예가 오래 남는다는 뜻이다. 사람들이 그 글씨를 읽으며 지나갔다면 많은 이의 신뢰를 얻어 영향력이 커진다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-050","preview":"연구나 조직 안에서 남모르게 성과를 거두는 꿈","description":"땅속을 자유롭게 걸어 다니거나 헤엄치듯 나아가는 꿈은 겉으로 드러나지 않는 곳에서 능력을 펼치는 것을 상징한다. 땅속은 남의 눈에 띄지 않는 깊은 영역을 뜻해, 그곳을 막힘없이 오간다는 것은 탐구나 내부의 일에서 실력을 인정받는 것으로 풀이된다. 땅속에서 반짝이는 광물이나 보물을 발견했다면 오래 파고든 일에서 뜻밖의 수확을 얻는다는 뜻이다. 땅 위로 다시 올라와 밝은 빛을 보았다면 숨은 노력이 드러나 공을 인정받는다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-051","preview":"구설과 다툼에 휘말려 큰 화를 겪는 흉몽","description":"지진으로 갈라진 땅 틈새로 떨어지는 꿈은 믿고 서 있던 기반이 갑자기 무너지는 위기를 상징한다. 지진은 예고 없이 닥치는 큰 혼란을, 틈새로 빠지는 것은 그 혼란에 붙잡혀 빠져나오기 어려운 처지를 뜻해 시비나 뜻밖의 재앙으로 풀이된다. 떨어지면서 누군가와 언쟁을 벌였다면 사소한 말싸움이 큰 분쟁으로 번질 수 있으니 말을 아끼는 것이 좋다. 틈새에서 스스로 기어 올라왔다면 어려움을 겪더라도 침착하게 대처해 위기를 넘긴다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-052","preview":"신분이 높아지고 바라던 자리에 오르는 길몽","description":"굵은 쇠기둥이 땅에 높이 박혀 우뚝 서 있는 꿈은 흔들리지 않는 지위와 든든한 기반을 상징한다. 쇠기둥은 건물을 떠받치는 단단한 힘을 뜻하기에, 그것이 높이 솟아 있다는 것은 입학이나 승진, 당선처럼 한 단계 올라서는 일로 풀이된다. 기둥을 손으로 짚었을 때 차갑고 단단하게 느껴졌다면 얻게 될 지위가 오래 이어진다는 뜻이다. 기둥 꼭대기에 깃발이 휘날렸다면 여러 사람 앞에서 이름을 떨치게 된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-053","preview":"병이나 궂은일로 손실과 곤란을 겪는 흉몽","description":"손에 든 물고기를 땅에 떨어뜨려 물고기가 팔딱거리는 꿈은 쥐고 있던 복이 손을 벗어나 힘겹게 버둥대는 상황을 상징한다. 물고기는 재물과 생기를 뜻하는데, 물을 떠나 땅에서 몸부림친다는 것은 건강이 상하거나 하는 일이 막혀 어려움을 겪는 것으로 풀이된다. 물고기가 끝내 움직임을 멈췄다면 손해가 커질 수 있으니 큰돈이 드는 결정은 미루는 것이 좋다. 물고기를 얼른 주워 물에 다시 넣어 주었다면 빠르게 대처해 피해를 줄인다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-054","preview":"집안이 크게 일어나고 큰 인물을 얻는 꿈","description":"땅속에 살던 용이 집 안으로 들어오는 꿈은 숨어 있던 큰 기운이 집에 깃드는 것을 상징한다. 용은 예로부터 권세와 부, 비범한 인물을 뜻해, 그 용이 집으로 들어온다는 것은 정신적·물질적 풍요가 한꺼번에 찾아오는 것으로 풀이된다. 용이 집 안에서 몸을 크게 펼치고 머물렀다면 그 복이 오래 이어진다는 뜻이다. 태몽이라면 장차 이름을 떨칠 아이를 낳는다는 뜻으로 전해진다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-055","preview":"이룬 일이 세상에 알려져 큰 영향을 미치는 꿈","description":"하늘의 태양이 땅으로 내려와 굴러다니는 꿈은 높은 곳에 있던 빛이 사람들 가까이 내려와 퍼지는 것을 상징한다. 태양은 모두를 비추는 큰 힘과 명성을 뜻하기에, 그것이 땅 위를 구른다는 것은 자신의 업적이나 결과물이 널리 퍼져 많은 이에게 닿는 것으로 풀이된다. 굴러가는 태양이 지나간 자리마다 환해졌다면 자신의 일이 주변에 좋은 변화를 일으킨다는 뜻이다. 태양을 두 손으로 받아 안았다면 그 명예를 온전히 자기 것으로 누리게 된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-056","preview":"막힘없이 모든 일이 술술 풀려 나가는 길몽","description":"발이 땅에 닿지 않을 만큼 가볍게 달려 나가는 꿈은 거칠 것 없이 앞으로 나아가는 기세를 상징한다. 몸이 가볍다는 것은 짐과 걱정에서 벗어난 상태를, 빠르게 달린다는 것은 일이 속도를 내어 진행되는 것을 뜻해 순풍을 받은 배처럼 순조로운 흐름으로 풀이된다. 달리는 내내 기분이 상쾌하고 웃음이 났다면 몸과 마음의 활력이 함께 높아진다는 뜻이다. 앞서 달리던 사람을 가볍게 앞질렀다면 경쟁에서 한발 앞서게 된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-057","preview":"자신의 주장과 힘이 세상에 인정받는 꿈","description":"칼이나 연장을 땅에 내리꽂아 땅이 갈라지는 꿈은 강한 의지로 굳은 벽을 뚫고 새 길을 여는 것을 상징한다. 칼과 연장은 자신의 실력과 권한을, 갈라지는 땅은 그 힘이 현실을 움직이는 것을 뜻해 학설이나 뜻이 널리 공인되고 주도권을 쥐는 것으로 풀이된다. 한 번에 깊이 박혀 땅이 시원하게 갈라졌다면 망설임 없이 추진한 일이 빠르게 성과를 낸다는 뜻이다. 갈라진 틈에서 맑은 물이 솟아났다면 그 성과가 많은 사람에게 이로움으로 돌아간다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-058","preview":"추진하던 일이 잘 풀려 큰돈을 벌게 되는 꿈","description":"돼지와 사람이 한데 어울려 즐겁게 노는 꿈은 재물이 사람 곁에 스스럼없이 머무는 것을 상징한다. 돼지는 재물과 풍요를 뜻하는데, 그것이 사람과 친근하게 어울린다는 것은 들어온 복이 달아나지 않고 생활 속에 자리 잡는 것으로 풀이된다. 함께 노는 사람이 가족이었다면 집안 전체의 살림이 넉넉해진다는 뜻이다. 놀이 끝에 돼지가 스스로 집 안으로 따라 들어왔다면 벌어들인 몫이 고스란히 쌓인다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-059","preview":"경쟁 상대에게 밀려 좌절을 맛보는 흉몽","description":"죽이려던 돼지가 갑자기 사람으로 바뀌는 꿈은 손에 넣었다고 여긴 것이 뜻밖의 상대로 돌변하는 것을 상징한다. 돼지는 쉽게 다룰 수 있는 대상이지만 사람은 맞서 겨룰 수 있는 존재여서, 이 변화는 얕보던 상대가 생각보다 강해 일이 뜻대로 되지 않는 것으로 풀이된다. 변한 사람이 오히려 자신을 꾸짖거나 쫓아왔다면 승부에서 지거나 체면을 잃을 수 있으니 무리한 대결은 피하는 것이 좋다. 그 사람과 대화로 화해했다면 다툼을 피하고 손해를 줄인다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-060","preview":"뜻밖의 횡재와 경사가 집안에 찾아오는 꿈","description":"새끼 돼지들이 어미의 젖을 빨아 먹는 꿈은 재물이 재물을 낳으며 불어나는 풍요를 상징한다. 어미 돼지는 넉넉한 밑천을, 젖을 먹고 자라는 새끼들은 그 밑천에서 생겨나는 이익을 뜻해 돈과 기쁜 일이 함께 들어오는 것으로 풀이된다. 새끼가 많고 젖을 힘차게 빨았다면 들어오는 재물이 여러 갈래로 늘어난다는 뜻이다. 어미 돼지가 편안히 누워 새끼들을 품고 있었다면 가족이 화목한 가운데 살림이 넉넉해진다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-061","preview":"처음엔 잘되던 장사가 결국 시들해지는 흉몽","description":"돼지가 작은 쥐로 바뀌어 쥐구멍으로 숨어드는 꿈은 커 보이던 이익이 점점 줄어들다 사라지는 것을 상징한다. 돼지는 넉넉한 재물을, 쥐는 몰래 빠져나가는 작은 손실을 뜻해 사업이 기대만큼 이어지지 못하는 것으로 풀이된다. 쥐를 잡으려다 놓쳤다면 새는 돈을 막지 못해 손해가 커질 수 있으니 지출과 거래를 꼼꼼히 살피는 것이 좋다. 쥐구멍을 미리 막아 두었다면 손실을 줄이고 버틸 힘을 지킨다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-062","preview":"예상치 못한 기쁜 소식과 큰 성과가 따르는 꿈","description":"아기돼지가 등장하는 꿈은 작지만 앞으로 크게 자랄 복이 찾아오는 것을 상징한다. 돼지는 재물과 풍요를, 아기돼지는 그 복이 막 싹트는 단계를 뜻해 생각하지 못한 곳에서 좋은 일이 시작되는 것으로 풀이된다. 아기돼지를 품에 안아 들어 올렸다면 반가운 연락이 오고, 함께 뛰어놀았다면 진행하던 일이 순조롭게 풀린다는 뜻이다. 아기돼지가 무럭무럭 자라 큰 돼지가 되었다면 들인 노력보다 큰 결실을 얻는다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-063","preview":"사업이 커지고 재물이 집안으로 모여드는 길몽","description":"돼지를 잡아 집으로 데려오는 꿈은 밖에서 얻은 풍요를 자기 살림 안으로 들이는 것을 상징한다. 돼지는 예로부터 다산과 넉넉함을 뜻해, 그것을 손수 잡아 온다는 것은 노력해서 얻은 성과가 재산으로 쌓인다는 의미로 풀이된다. 데려온 돼지가 살이 오르고 새끼를 쳤다면 벌여 둔 일이 날로 커져 수익이 늘어난다는 뜻이다. 다만 데려오는 길에 돼지를 놓쳤다면 들어오던 재물을 끝까지 챙기지 못할 수 있으니 마무리를 단단히 하라는 뜻으로 본다.","tags":["조건부","길몽"],"is_lucky":"lucky","luck_index":75},
{"id":"crawled-064","preview":"작업과 연구가 좋은 결실과 이익을 맺는 꿈","description":"한 마리였던 돼지가 순식간에 여러 마리로 불어나는 꿈은 하나의 노력이 여러 갈래의 성과로 번지는 것을 상징한다. 돼지는 재물과 풍요를 뜻하는데, 그 수가 저절로 늘어난다는 것은 공들인 작품이나 탐구가 인정받아 보상이 연이어 생기는 것으로 풀이된다. 불어난 돼지들이 모두 살지고 건강했다면 얻게 될 성과의 질도 높다는 뜻이다. 돼지들이 질서 있게 한 우리에 모였다면 늘어난 몫을 잘 관리해 오래 지킨다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-065","preview":"재물복을 타고난 자녀를 두게 되는 꿈","description":"여러 마리의 새끼돼지를 한꺼번에 품에 끌어안는 꿈은 집안에 복을 안고 올 새 식구를 맞이하는 것을 상징한다. 새끼돼지는 앞으로 커 갈 재물과 다산을 뜻하기에, 그것을 품에 안는다는 것은 넉넉한 운을 지닌 아이를 얻는 것으로 풀이된다. 새끼들이 품 안에서 얌전히 잠들었다면 아이가 순하고 건강하게 자란다는 뜻이다. 품에 안은 새끼돼지의 털이 윤기 나고 통통했다면 그 아이가 커서 살림을 크게 일으킨다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-066","preview":"조직의 우두머리가 되고 막힌 일이 풀리는 꿈","description":"돼지를 통째로 삶거나 구워 잘라 먹는 꿈은 큰 몫을 자기 손으로 나누고 차지하는 힘을 상징한다. 통째로 마련한 돼지는 여러 사람이 함께 나눌 큰 재물과 권한을 뜻해, 그것을 직접 잘라 먹는다는 것은 무리를 이끄는 자리에 오르거나 오래 묵은 문제가 해결되어 활기를 되찾는 것으로 풀이된다. 고기를 여러 사람에게 고루 나누어 주었다면 사람들의 신망을 얻어 자리가 더욱 굳어진다는 뜻이다. 고기 맛이 좋고 배가 든든했다면 몸과 형편이 함께 넉넉해진다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-067","preview":"지위와 복록이 함께 높아지는 큰 성공의 꿈","description":"돼지가 뒤를 따라오거나 그 돼지를 집 안으로 들이는 꿈은 밖에 있던 복이 자기 집 문턱을 넘는 것을 상징한다. 돼지는 재물과 풍요의 대표적인 상징이라, 스스로 따라오거나 집 안에 들어선다는 것은 계약 성사나 사업 번창, 좋은 혼사처럼 기쁜 일이 이어지는 것으로 풀이된다. 따라오는 돼지가 크고 살져 있었다면 얻게 될 몫이 그만큼 크다는 뜻이다. 집 안에 들인 돼지가 편안히 자리를 잡았다면 들어온 복이 오래 머문다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-068","preview":"가르치거나 쓰는 일, 사업으로 이름을 날리는 꿈","description":"돼지우리에 돼지가 가득하고 새끼들이 우글거리는 꿈은 자신이 일군 터전에서 결실이 넘쳐 나는 것을 상징한다. 우리 안의 많은 돼지는 쌓인 재물과 따르는 사람들을 뜻해, 작가나 교육자, 사업가로서 많은 이에게 영향을 미치며 명성을 얻는 것으로 풀이된다. 새끼들이 건강하게 뛰놀았다면 뒤를 잇는 제자나 후배가 잘 자라 자신을 더 빛낸다는 뜻이다. 우리를 넓히거나 새로 지었다면 하는 일의 규모가 커진다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-069","preview":"높은 자리에 오르거나 학문의 길을 걷는 꿈","description":"산돼지들이 떼를 지어 부엌으로 몰려드는 꿈은 거센 기운이 집안 살림의 한가운데로 들어오는 것을 상징한다. 부엌은 집안의 생계와 재물을 다루는 곳이고 힘센 산돼지 떼는 큰 세력을 뜻해, 높은 직위를 얻거나 공부에서 두각을 나타내는 것으로 풀이된다. 산돼지들이 부엌을 어지럽히지 않고 얌전히 머물렀다면 얻은 지위를 차분히 지켜 낸다는 뜻이다. 산돼지 떼를 직접 이끌고 들어왔다면 여러 사람을 거느리는 자리에 오른다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-070","preview":"가족에게 좋은 인연이나 새 생명이 깃드는 꿈","description":"뱀이 가족을 무는 꿈은 그 가족에게 강한 기운이 옮겨 가 삶에 새로운 활력이 생기는 것을 상징한다. 뱀은 예로부터 재물과 생명력, 남녀의 인연을 함께 뜻해, 뱀에게 물린 사람이 그 기운을 직접 받게 된다고 풀이된다. 물린 가족이 아파하지 않고 오히려 담담했다면 연애나 출산처럼 반가운 일이 그 사람에게 먼저 찾아온다는 뜻이다. 그런 일과 거리가 먼 가족이라면 뜻밖의 돈이나 재물이 들어오는 쪽으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-071","preview":"손에 쥘 재물과 든든한 조력자가 함께 오는 길몽","description":"뱀이 손을 무는 꿈은 무언가를 붙잡고 일구는 힘에 새로운 기운이 더해지는 것을 상징한다. 손은 일하고 재물을 거두는 몸의 부위이고 뱀은 재물과 지혜를 뜻해, 둘이 맞닿는 장면이 하는 일에 돈과 도움이 따르는 것으로 풀이된다. 물린 손이 아프지 않고 오히려 따뜻하게 느껴졌다면 곁에서 힘이 되어 줄 사람을 곧 만나게 된다는 뜻이다. 물린 뒤 뱀을 손으로 붙잡았다면 들어온 기회를 스스로 잘 활용하게 된다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-072","preview":"여러 갈래로 복이 몰려드는 기운찬 길몽","description":"살아 움직이는 뱀이 여럿 나타나는 꿈은 재물과 사람의 도움이 한꺼번에 모여드는 흐름을 상징한다. 뱀 한 마리 한 마리가 재물과 인연을 뜻하는 것으로 여겨져, 그 수가 많을수록 들어오는 운도 커진다고 풀이된다. 뱀들이 자신을 둘러싸도 무섭지 않고 편안했다면 주변 사람들이 기꺼이 힘을 보태 일이 순조롭게 풀린다는 뜻이다. 뱀들이 집 안이나 일터로 줄지어 들어왔다면 그 복이 살림이나 사업으로 이어진다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-073","preview":"따르는 사람을 거느리며 세력을 키우는 길몽","description":"큰 뱀 곁에 작은 뱀이 붙어 있는 꿈은 중심이 되는 존재와 그를 따르는 무리가 함께 자리 잡는 모습을 상징한다. 큰 뱀은 힘과 권위를, 작은 뱀은 그 곁을 지키는 사람들을 뜻해, 장차 권력과 영향력을 쥐게 된다는 의미로 풀이된다. 큰 뱀이 작은 뱀을 품듯 감싸고 있었다면 아랫사람이나 후배의 신망을 얻어 자리가 단단해진다는 뜻이다. 두 뱀이 나란히 같은 곳을 향해 나아갔다면 뜻이 맞는 사람과 손잡고 큰일을 이루게 된다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-074","preview":"평생을 함께할 짝이나 동지를 만나게 되는 꿈","description":"큰 뱀에게 물리는 꿈은 강하고 든든한 존재와 깊이 엮이게 되는 것을 상징한다. 뱀이 무는 것은 그 기운이 몸에 스며드는 것으로 여겨지고, 뱀이 클수록 그 인연도 크고 오래간다고 풀이된다. 물리고도 두렵지 않았다면 오래 곁을 지킬 배우자나 뜻을 같이할 사람이 나타난다는 뜻이다. 물린 자리에서 따뜻한 기운이 퍼지는 느낌이 들었다면 그 인연이 삶에 큰 힘이 된다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-075","preview":"가까운 사이가 연인으로 발전하는 사랑의 길몽","description":"뱀에게 물리는 꿈은 마음을 흔드는 강한 끌림이 삶에 들어오는 것을 상징한다. 뱀은 예로부터 남녀의 정과 인연을 뜻하는 동물로 여겨져, 그 뱀이 무는 장면이 누군가와 깊이 맺어지는 것으로 풀이된다. 이미 마음을 둔 사람이 있다면 관계가 한 걸음 더 깊어져 혼인까지 이어질 수 있다는 뜻이다. 물린 뒤 설레거나 기분이 좋았다면 새로 만나는 인연이 오래도록 좋은 관계로 남는다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-076","preview":"타오르는 기세만큼 재산이 불어나는 길몽","description":"불이 나는 꿈은 삶에 강한 기운이 일어나 큰 변화와 성취로 이어지는 것을 상징한다. 불은 번지고 커지는 성질 때문에 재물과 일이 빠르게 늘어나는 것과 연결되어, 예로부터 반가운 꿈으로 풀이된다. 불길이 크고 밝게 치솟았다면 그만큼 하는 일의 성과도 크게 드러난다는 뜻이다. 불을 바라보며 두렵기보다 시원하고 후련했다면 오래 묵은 답답함이 풀리고 새 출발을 하게 된다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-077","preview":"이름이 널리 알려지고 명예가 높아지는 길몽","description":"자신의 몸에 불이 붙는 꿈은 스스로가 주목받는 중심에 서게 되는 것을 상징한다. 불은 금전운과 기세를 뜻하는데, 그것이 다른 곳이 아닌 몸에 붙었다는 점에서 운이 본인에게 곧장 깃든다고 풀이된다. 불이 붙었는데도 뜨겁지 않고 오히려 환하게 빛났다면 사람들의 인정과 존중을 얻게 된다는 뜻이다. 불붙은 채로 사람들 앞에 섰다면 자신의 재능이 세상에 드러나 자주 입에 오르내리게 된다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-078","preview":"일터의 기세가 오르며 경력이 단단해지는 길몽","description":"회사에 불이 나는 꿈은 몸담은 일터에 강한 기운이 일어 일과 위치가 크게 움직이는 것을 상징한다. 불은 번성과 재물을 뜻해, 그 불이 일터에서 일어난다는 것은 맡은 일과 사업이 커지는 쪽으로 풀이된다. 불이 난 회사 안에서 동료들과 함께 침착하게 움직였다면 함께 일하는 사람들과 힘을 모아 성과를 내게 된다는 뜻이다. 불이 꺼진 뒤 건물이 더 크고 새롭게 보였다면 일터에 좋은 변화가 생겨 자리가 한층 넓어진다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-079","preview":"집안에 큰 금전운이 밀려드는 반가운 꿈","description":"건물에 불이 나는 꿈은 머무는 터전 전체에 왕성한 기운이 차오르는 것을 상징한다. 불은 크게 번질수록 그 기세가 세지는데, 이것이 살림이 넉넉해지고 재물이 늘어나는 흐름과 이어져 풀이된다. 불난 건물을 보며 크게 울었다면 그 울음만큼 쌓였던 마음이 풀리고 좋은 일이 더 크게 찾아온다는 뜻이다. 건물에서 연기보다 밝은 불꽃이 먼저 보였다면 기다리던 일이 막힘없이 이루어진다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-080","preview":"애써 키운 성과가 꺾일 수 있음을 알리는 흉몽","description":"소화기로 불을 끄는 꿈은 스스로 일어나던 좋은 기운을 가라앉히는 것을 상징한다. 불은 명예와 부를 뜻하는데, 그것을 직접 꺼 버린다는 점에서 하던 일이 실패하거나 큰 고비를 맞을 수 있다고 풀이된다. 불을 끄고 나서 허탈하거나 아쉬웠다면 지금 붙잡고 있는 기회를 너무 쉽게 내려놓지 않도록 조심하라는 뜻이다. 불이 다 꺼진 뒤 주변이 어둡고 쓸쓸했다면 한동안 일이 더디게 풀릴 수 있으니 무리한 결정을 미루는 것이 좋다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-081","preview":"다가온 행운을 스스로 놓쳐 버리기 쉬운 흉몽","description":"불이 나 급히 대피하는 꿈은 찾아온 기회 앞에서 몸을 사리고 물러서는 마음을 상징한다. 불은 재물과 성공의 기운을 뜻하는데, 그것을 피해 달아난다는 점에서 손에 들어올 운을 피하는 것과 같다고 풀이된다. 대피하면서 무엇을 두고 왔다고 아쉬워했다면 망설이는 사이 기회를 흘려보내 좌절을 겪을 수 있다는 뜻이다. 남들은 그대로 있는데 혼자만 서둘러 빠져나왔다면 지나친 걱정 때문에 좋은 흐름을 스스로 막을 수 있으니 조심하라는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-082","preview":"재물과 새 인연이 한꺼번에 찾아오는 길몽","description":"뱀에 물리는 꿈은 강한 기운이 몸 안으로 곧장 들어와 삶의 흐름이 크게 바뀌는 것을 상징한다. 뱀은 재물과 생명력을 함께 뜻하는데, 그것이 살갗을 뚫고 들어온다는 것은 그 기운을 온전히 내 것으로 받아들인다는 의미로 풀이된다. 물린 뱀이 크고 빛깔이 고왔다면 그만큼 큰 운이 따른다는 뜻이며, 아이를 바라는 이에게는 좋은 태몽으로도 해석된다. 다만 물린 뒤 고통이 심해 쓰러졌다면 들어온 기운이 지나쳐 탈이 날 수 있으니 무리하지 말라는 뜻으로 본다.","tags":["조건부","길몽","태몽"],"is_lucky":"lucky","luck_index":75},
{"id":"crawled-083","preview":"지혜와 변화의 기운이 상황 따라 달리 풀리는 꿈","description":"뱀이 나오는 꿈은 삶에 새로운 기운이 스며들어 무언가가 바뀌기 시작하는 때를 상징한다. 뱀은 허물을 벗고 다시 태어나는 동물이라 지혜와 재생을 뜻하면서도, 땅속에 숨어 사는 습성 때문에 드러나지 않은 위험을 뜻하기도 해 해석이 여러 갈래로 나뉜다. 뱀이 머리를 들고 자신을 가만히 바라보았다면 앞길을 이끌어 줄 사람이나 재물의 기회가 다가온다는 뜻으로 해석된다. 다만 뱀이 금세 자취를 감추었거나 빛깔이 검었다면 반가운 일이 오래 머물지 않거나 뜻밖의 걱정이 생길 수 있으니 조심하라는 뜻으로 본다.","tags":["조건부"],"is_lucky":"conditional","luck_index":50},
{"id":"crawled-084","preview":"큰 과제를 해내고 일터에서 인정받는 길몽","description":"큰 뱀을 죽이는 꿈은 앞을 가로막던 커다란 벽을 스스로 넘어서는 것을 상징한다. 큰 뱀은 쉽게 다룰 수 없는 일이나 경쟁을 뜻해, 그것을 이겨 낸다는 점에서 중요한 프로젝트나 취업에서 성공을 거두는 것으로 풀이되고 뱀이 클수록 그 운도 크다고 본다. 뱀을 쓰러뜨린 뒤 주변 사람들이 박수를 쳤다면 그 성과가 널리 알려져 평판이 높아진다는 뜻이다. 싸움이 길었지만 끝까지 물러서지 않았다면 어려운 시험이나 협상에서 끈기로 결실을 맺게 된다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-085","preview":"건강에 빨간불이 켜졌음을 알리는 경고의 흉몽","description":"검은 뱀이 나타나는 꿈은 몸과 마음에 어두운 기운이 드리우는 것을 상징한다. 뱀 꿈에서는 색이 중요하게 여겨지는데, 검은빛은 생기가 꺼지는 것과 연결되어 죽음이나 질병 같은 건강 문제를 암시하는 것으로 풀이된다. 검은 뱀이 집 안으로 스며들었다면 가족 가운데 몸이 약한 사람이 생길 수 있으니 미리 건강을 살피는 것이 좋다. 검은 뱀과 눈이 마주쳐 오싹했다면 무리한 일정이나 과로를 줄이고 쉬어 가라는 경고로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-086","preview":"방해물을 지혜롭게 걷어 내고 앞길을 여는 길몽","description":"뱀의 머리를 자르는 꿈은 문제의 핵심을 정확히 짚어 단번에 끊어 내는 것을 상징한다. 뱀은 지혜와 꾀를 뜻하고 머리는 그 중심이라, 머리를 자른다는 것은 얽힌 일을 근본부터 정리한다는 의미로 풀이된다. 단칼에 깔끔하게 잘랐다면 오래 끌던 고민이 의외로 쉽게 해결된다는 뜻이다. 여성이 이 꿈을 꾸었다면 영리한 딸을 얻는 태몽으로도 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-087","preview":"신경 쓰일 경쟁자나 불청객이 다가오는 흉몽","description":"뱀에게 쫓기는 꿈은 피하고 싶은 문제가 끈질기게 따라붙는 상황을 상징한다. 뱀은 꾀가 많고 집요한 동물로 여겨져, 그것에 쫓긴다는 것은 누군가와 부딪히거나 원치 않는 일에 엮이게 된다는 의미로 풀이된다. 쫓아오던 뱀이 검은색이었다면 그 갈등이 더 깊어져 손해를 볼 수 있으니 조심해야 한다. 막다른 곳에 몰려 숨이 막혔다면 혼자 감당하려 하지 말고 주변에 도움을 청하라는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-088","preview":"일이 꼬여 곤경에 빠질 수 있음을 알리는 흉몽","description":"뱀이 몸을 휘감고 있는 꿈은 손발이 묶인 듯 마음대로 움직일 수 없는 답답한 처지를 상징한다. 뱀이 조여 오는 힘은 벗어나기 어려운 압박을 뜻해, 하던 일이 막히거나 뜻밖의 사건에 휘말리게 된다고 풀이된다. 숨이 막힐 만큼 조여 와 몸부림쳤다면 주변 사람과의 문제로 마음고생이 길어질 수 있으니 조심해야 한다. 누군가 다가와 뱀을 떼어 주었다면 혼자서는 어렵던 문제를 도와줄 사람이 나타난다는 뜻으로 해석된다.","tags":["조건부","흉몽"],"is_lucky":"unlucky","luck_index":30},
{"id":"crawled-089","preview":"뜻밖의 돈과 사람들의 존경이 함께 찾아오는 꿈","description":"뱀이 몸을 감싸는 꿈은 큰 기운이 자신을 품듯 둘러싸 보호하는 것을 상징한다. 뱀은 재물과 생명력을 뜻하는데, 그것이 몸에 감긴다는 점에서 노리지 않던 재물이 저절로 따라붙는다고 풀이된다. 뱀이 부드럽게 감겨 따뜻하게 느껴졌다면 주변에서 신뢰와 존중을 받게 된다는 뜻이다. 감긴 뱀이 금빛으로 빛났다면 그 재물이 생각보다 크게 불어난다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-090","preview":"귀한 손님과 도와줄 사람이 집으로 찾아드는 길몽","description":"집 안에 뱀이 나타나는 꿈은 삶의 터전에 새로운 기운과 인연이 들어서는 것을 상징한다. 예로부터 집에 사는 뱀은 집안을 지키고 복을 불러오는 존재로 여겨져, 그 뱀을 보는 것이 집안에 좋은 일이 생길 조짐으로 풀이된다. 뱀이 대문으로 천천히 들어와 자리를 잡았다면 귀인이 오래 곁에 머물며 힘이 되어 준다는 뜻이다. 뱀이 곳간이나 부엌 쪽으로 향했다면 살림이 넉넉해지고 집안 형편이 나아진다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-091","preview":"노력한 만큼 돈과 재운이 손에 들어오는 길몽","description":"뱀을 잡는 꿈은 눈앞에 나타난 기회를 제 손으로 붙드는 것을 상징한다. 뱀은 재물을 뜻하는 대표적인 상징이라, 날쌘 뱀을 붙잡는다는 것은 쉽게 잡히지 않던 돈을 끝내 거머쥔다는 의미로 풀이된다. 잡은 뱀이 황금빛이나 갈색으로 윤기가 돌았다면 그만큼 큰 재운이 따른다는 뜻이다. 다만 잡았던 뱀이 손에서 빠져나갔다면 들어온 재물을 지키지 못할 수 있으니 씀씀이를 살피라는 뜻으로 본다.","tags":["조건부","길몽"],"is_lucky":"lucky","luck_index":75},
{"id":"crawled-092","preview":"막혔던 일이 자기 힘으로 술술 풀리는 길몽","description":"뱀을 잡아먹는 꿈은 마음을 무겁게 하던 근심을 자신의 것으로 삼켜 이겨 내는 것을 상징한다. 뱀은 걱정거리를 뜻하기도 하는데, 그것을 먹어 치운다는 점에서 문제를 피하지 않고 스스로 해결한다는 의미로 풀이된다. 맛있게 먹고 배가 든든했다면 해결한 일에서 실속까지 챙기게 된다는 뜻이다. 여성이 꾸었다면 야무진 딸을 얻는 태몽으로도 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-093","preview":"돈의 기회와 기력 쇠퇴가 함께 비치는 꿈","description":"죽은 뱀을 보는 꿈은 한동안 이어지던 기운이 멈추고 한 시기가 마무리되는 것을 상징한다. 뱀은 재물과 생명력을 함께 뜻해, 움직임을 멈춘 뱀은 떠돌던 재물이 손에 잡히는 결과로 남는다는 의미와 함께 생명력이 약해진다는 의미로도 풀이된다. 죽은 뱀을 담담하게 치웠다면 미뤄 두었던 돈 문제가 정리되며 생각지 못한 수입이 생긴다는 뜻으로 해석된다. 다만 몸이 고단한 때라면 기력이 떨어질 수 있으니 건강을 먼저 챙기라는 뜻으로 보며, 태몽이라면 좋지 않게 풀이된다.","tags":["조건부"],"is_lucky":"conditional","luck_index":50},
{"id":"crawled-094","preview":"성공의 기회가 스스로 찾아와 안기는 길몽","description":"뱀이 달려드는 꿈은 기다리던 운이 자신을 향해 곧장 몰려오는 것을 상징한다. 뱀은 재물과 성공의 기운을 뜻해, 그것이 망설임 없이 달려든다는 것은 일이 빠르게 무르익는다는 의미로 풀이된다. 달려드는 뱀 앞에서 겁먹지 않고 당당히 맞섰다면 큰일을 맡아 성과를 거둔다는 뜻이다. 다만 뱀을 피해 멀리 달아났다면 손에 들어올 운을 스스로 놓칠 수 있으니 머뭇거리지 말라는 뜻으로 본다.","tags":["조건부","길몽"],"is_lucky":"lucky","luck_index":75},
{"id":"crawled-095","preview":"든든한 투자자를 만나 사업이 크게 번창하는 꿈","description":"돼지가 손을 무는 꿈은 재물이 스스로 다가와 자신과 단단히 이어지는 것을 상징한다. 돼지는 예로부터 재물과 복을 뜻하는데, 그 돼지가 일하는 손을 문다는 점에서 하는 일에 돈과 도움이 붙는다고 풀이된다. 물린 손이 아프지 않고 돼지가 순하게 매달려 있었다면 믿을 만한 동업자나 후원자를 얻게 된다는 뜻이다. 돼지가 여러 번 물며 따라왔다면 한 번으로 끝나지 않고 계속해서 수익이 들어온다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-096","preview":"합격이나 승진처럼 노력의 결실을 거두는 길몽","description":"산속에서 멧돼지를 죽이는 꿈은 거칠고 힘센 상대를 이겨 원하는 것을 차지하는 것을 상징한다. 멧돼지는 재물과 함께 사나운 기세를 뜻해, 그것을 쓰러뜨린다는 것은 행운과 금전적 이득을 손에 넣는 것으로 풀이된다. 멧돼지를 쓰러뜨린 뒤 짊어지고 집으로 돌아왔다면 얻은 성과가 집안 살림에 보탬이 된다는 뜻이다. 여럿이 힘을 모아 멧돼지를 잡았다면 함께하는 사람들과 성과를 나누며 관계도 깊어진다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-097","preview":"뜻밖의 행운과 금전적 이득이 몰려오는 길몽","description":"멧돼지가 달려드는 꿈은 거침없는 기세가 자신에게 곧장 향하는 것을 상징한다. 멧돼지는 힘과 풍요를 뜻하는 짐승이라, 그것이 다가온다는 것은 큰 재물이 들어오는 길이 열린다는 의미로 풀이된다. 아이를 바라는 이에게는 용맹하고 이름을 떨칠 아이를 얻는 태몽으로도 해석된다. 다만 겁에 질려 도망쳤다면 들어올 돈을 놓치거나 손해를 볼 수 있으니 기회를 피하지 말라는 뜻으로 본다.","tags":["조건부","길몽","태몽"],"is_lucky":"lucky","luck_index":75},
{"id":"crawled-098","preview":"이름을 떨칠 씩씩한 사내아이를 얻는 꿈","description":"멧돼지에게 쫓기는 꿈은 힘찬 기운이 자신을 향해 끈질기게 따라오는 것을 상징한다. 멧돼지는 용맹함과 큰 기세를 뜻해, 그 기운이 자신에게 다가온다는 점에서 높은 관직과 명성을 누릴 아이를 품게 된다는 태몽으로 풀이된다. 쫓기면서도 두렵기보다 신기하고 설렜다면 아이가 건강하고 활달하게 자란다는 뜻이다. 태몽과 거리가 먼 사람이라면 미루던 일을 서두르게 만드는 좋은 자극이 찾아온다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-099","preview":"재물과 이권을 손에 넣게 되는 손꼽히는 길몽","description":"돼지를 잡는 꿈은 오래 노리던 몫을 마침내 자기 것으로 만드는 것을 상징한다. 돼지는 예로부터 재물과 풍요를 뜻해, 그것을 붙잡는다는 것은 돈이나 권리를 실제로 얻게 되는 것으로 풀이되며 꿈을 꾼 뒤 현실에서 이루어지는 일이 많다고 전해진다. 살찐 돼지를 힘들이지 않고 붙잡았다면 생각보다 쉽게 큰 이득을 얻게 된다는 뜻이다. 잡은 돼지를 집으로 데려왔다면 그 재물이 살림에 오래 남아 집안을 넉넉하게 한다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-100","preview":"돈이 쌓이고 투자마다 큰 성과를 거두는 길몽","description":"돼지우리에 똥이 수북하게 쌓인 꿈은 재물이 넘칠 만큼 차오르는 넉넉한 상태를 상징한다. 돼지와 똥은 모두 예로부터 재물을 뜻하는 상징이라, 둘이 함께 쌓여 있다는 것은 사업이 번창하고 돈이 크게 불어나는 것으로 풀이된다. 쌓인 똥을 치우다 손이나 옷에 묻었다면 그 재물이 직접 자신의 몫으로 들어온다는 뜻이다. 냄새가 나도 싫지 않고 오히려 흐뭇했다면 부동산 같은 큰 거래에서도 좋은 결과를 얻게 된다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-101","preview":"시작은 순조로워도 끝이 아쉽게 끝나는 흉몽","description":"돼지를 칼로 찌르거나 죽이는 꿈은 손에 들어온 복을 스스로 해치는 것을 상징한다. 돼지는 재물과 풍요를 뜻해, 그것을 칼로 상하게 한다는 점에서 일의 결실이 기대에 못 미치거나 어긋난다고 풀이된다. 찌른 뒤 피가 많이 흘러 겁이 났다면 무리하게 밀어붙인 일에서 손해를 볼 수 있으니 조심해야 한다. 죽인 돼지를 그대로 두고 떠났다면 마무리를 소홀히 해 다 된 일이 틀어질 수 있다는 경고로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-102","preview":"투자와 행운이 모두 따르는 손꼽히는 길몽","description":"돼지를 보는 꿈은 넉넉한 재물과 복이 가까이 다가와 있음을 상징한다. 돼지는 예로부터 재물과 다산을 뜻하는 대표적인 동물로 여겨져, 복권 당첨처럼 뜻밖의 큰돈과 연결되어 풀이된다. 돼지가 살이 오르고 윤기가 흘렀다면 주식이나 채권 같은 곳에서 기대 이상의 수익을 얻게 된다는 뜻이다. 돼지가 자신을 향해 다가왔다면 하는 일마다 운이 트여 막힘없이 풀린다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-103","preview":"손대는 일마다 큰돈이 들어오는 운수 대길한 꿈","description":"돼지가 금은보화를 토해내는 꿈은 이미 품고 있던 복이 눈에 보이는 재물로 쏟아져 나오는 것을 상징한다. 돼지와 금은보화는 모두 재물을 뜻해, 그 둘이 한 장면에 겹친다는 것은 투자나 사업이 크게 성공해 많은 돈을 벌게 되는 것으로 풀이된다. 쏟아진 보화를 두 손 가득 주워 담았다면 그 이익을 놓치지 않고 고스란히 챙기게 된다는 뜻이다. 보화가 끝없이 나와 주변 사람과 나누었다면 얻은 재물로 인심까지 얻게 된다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-104","preview":"돈 문제로 구설에 오를 수 있음을 알리는 흉몽","description":"돼지에게서 도망치는 꿈은 다가오는 재물과 얽힌 일을 피하고 싶어 하는 마음을 상징한다. 돼지는 재물을 뜻하는데, 그것에 쫓겨 달아난다는 점에서 돈을 둘러싼 말썽이나 시비에 휘말릴 수 있다고 풀이된다. 도망치다 넘어지거나 붙잡혔다면 금전 문제로 남의 입에 오르내릴 수 있으니 말과 행동을 조심해야 한다. 이 꿈을 꾸었다면 재물을 탐하기보다 사람을 얻는 데 마음을 쓰는 것이 좋다고 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-105","preview":"큰 조직을 이끄는 우두머리 자리에 오르는 길몽","description":"용이 하늘로 오르는 꿈은 오랜 준비 끝에 가장 높은 곳에 다다르는 것을 상징한다. 용은 예로부터 임금과 최고의 권위를 뜻해, 그 용이 승천한다는 것은 높은 지위나 리더의 자리를 얻게 되는 것으로 풀이된다. 용이 구름을 뚫고 오를 때 하늘이 환하게 밝아졌다면 그 성공이 널리 알려져 많은 사람의 존경을 받게 된다는 뜻이다. 용이 오르기 전 자신을 돌아보며 고개를 숙였다면 윗사람의 인정과 도움을 받아 뜻을 이루게 된다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-106","preview":"귀 건강에 탈이 날 수 있어 유의해야 하는 흉몽","description":"용에게 귀를 물리는 꿈은 듣고 받아들이는 감각에 강한 충격이 가해지는 것을 상징한다. 용은 거대한 힘을 뜻하는데, 그 힘이 하필 귀를 문다는 점에서 귀와 관련된 병이나 청력 문제를 조심하라는 뜻으로 풀이된다. 물린 귀에서 피가 나거나 소리가 잘 들리지 않았다면 미루던 검진을 받아 보는 것이 좋다. 물린 뒤 주변 말소리가 시끄럽게 울렸다면 남의 말에 휘둘려 일을 그르칠 수 있으니 조심하라는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-107","preview":"뛰어난 사람과 귀한 글을 가까이하게 되는 꿈","description":"용을 그린 그림을 바라보는 꿈은 큰 뜻과 재능을 곁에서 보고 배우게 되는 것을 상징한다. 용은 뛰어난 인물과 높은 명성을 뜻하는데, 그것이 예술품의 모습으로 나타난다는 점에서 학문이나 책과 관련된 일, 이름난 사람과의 인연으로 풀이된다. 그림 속 용이 살아 움직이는 듯 생생했다면 그 인연이 실제로 큰 도움이 되어 하는 일이 빛을 본다는 뜻이다. 용 문신을 한 사람을 보았다면 이름이 알려지거나 쉽게 접하기 어려운 자료를 얻게 된다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-108","preview":"오래 바라던 소망과 계획이 마침내 이루어지는 꿈","description":"용에게 물려 죽는 꿈은 지금까지의 자신이 끝나고 더 큰 존재로 다시 태어나는 것을 상징한다. 꿈에서 죽음은 끝이 아니라 새로운 시작을 뜻하는 경우가 많고 용은 최고의 힘을 뜻해, 그 힘에 의해 다시 태어난다는 점에서 뜻한 일이 성사된다고 풀이된다. 죽는 순간 두렵기보다 평온했다면 애써 준비한 일이 큰 탈 없이 마무리된다는 뜻이다. 용이 자신을 삼킨 뒤 하늘로 올랐다면 그 성공이 생각보다 더 크게 이어진다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-109","preview":"복권이나 부동산으로 큰 부를 거머쥐는 길몽","description":"용에게 물려 피투성이가 된 채 도망쳐 나오는 꿈은 큰 힘과 맞부딪친 끝에 그 기운을 몸에 지니고 돌아오는 것을 상징한다. 꿈에서 피는 재물을 뜻하는 경우가 많고 용은 거대한 운을 뜻해, 피를 많이 흘릴수록 들어오는 재물도 크다고 풀이된다. 도망쳐 나온 뒤 안도감이 크게 밀려왔다면 큰 거래나 매매에서 뜻밖의 이득을 얻게 된다는 뜻이다. 피투성이인 자신을 보고도 아프지 않았다면 그 행운이 고스란히 자신의 몫으로 남는다는 의미로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-110","preview":"귀한 자식을 얻지만 속을 썩일 일도 따르는 꿈","description":"용이 손가락을 무는 꿈은 큰 기운을 지닌 자식이 집안에 들어오되 그 기운이 다루기 쉽지 않은 것을 상징한다. 용은 귀한 아들을 뜻하는 태몽의 상징이지만, 손가락을 문다는 것은 그 힘이 부모를 향해 부딪쳐 오는 것으로 여겨져 자라며 말썽을 일으킬 수 있다는 의미로 풀이된다. 물린 손가락에서 피가 나거나 통증이 오래갔다면 아이의 고집이나 문제로 마음고생을 할 수 있다는 뜻으로 해석된다. 용이 문 뒤 곧 놓아주고 곁에 머물렀다면 애를 먹이더라도 결국 부모 곁으로 돌아온다는 뜻으로 본다.","tags":[],"is_lucky":"neutral","luck_index":50},
{"id":"crawled-111","preview":"집안이 크게 번창하고 재물이 들어오는 길몽","description":"집에 불이 나는 꿈은 집안에 강한 기운이 일어나 살림이 크게 일어서는 것을 상징한다. 불은 타오르며 번져 나가는 성질 때문에 세력과 재물이 불어나는 것으로 여겨져, 집이 불길에 휩싸이는 장면이 오히려 번영의 징조로 풀이된다. 불길이 높이 치솟고 환하게 빛났다면 그만큼 큰 운이 찾아온다는 뜻이다. 다만 불이 꺼지고 재만 남았다면 일어난 운이 오래가지 못할 수 있으니 얻은 것을 잘 지키라는 뜻으로 본다.","tags":["조건부","길몽"],"is_lucky":"lucky","luck_index":75},
{"id":"crawled-112","preview":"추진하던 목표가 마침내 이루어지는 길몽","description":"자동차에 불이 붙는 꿈은 자신을 앞으로 이끌던 열정이 절정에 이르는 것을 상징한다. 자동차는 자신의 추진력이나 자기 자신을 뜻하고 불은 왕성하게 일어나는 기운을 뜻해, 둘이 만나는 장면이 하는 일에서 큰 성과를 거두는 조짐으로 풀이된다. 불타는 차를 몰고 그대로 달려 나갔다면 거침없는 기세로 경쟁에서 앞서 나가게 된다는 뜻으로 해석된다. 불길을 바라보며 마음이 벅차올랐다면 오래 품어 온 바람을 스스로 이루어 낸다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-113","preview":"손에 들어온 금전운을 스스로 놓치는 흉몽","description":"불이 난 것을 직접 끄는 꿈은 막 일어나려던 좋은 기운을 스스로 가라앉히는 것을 상징한다. 불은 재물과 번창의 기세로 풀이되는데, 그 불길을 자기 손으로 잡는 것은 다가온 운을 붙잡지 못하고 흘려보내는 행동과 이어진다. 물을 끼얹으며 다급하고 초조했다면 사업이 기울거나 금전 손실이 생길 수 있으니 무리한 결정을 삼가라는 경고로 풀이된다. 불을 끈 뒤에도 연기가 계속 피어올랐다면 정리했다고 여긴 문제가 다시 번질 수 있다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-114","preview":"지혜와 아이디어로 성공을 거머쥐는 길몽","description":"머리에 불이 붙는 꿈은 생각과 지혜가 활활 타오르듯 왕성해지는 것을 상징한다. 머리는 지식과 판단을, 불은 재물과 명예가 일어나는 기운을 뜻해, 머리에서 불이 타오르는 것은 자신의 머리로 이름을 얻게 되는 조짐으로 풀이된다. 불이 붙었는데도 뜨겁지 않고 머리가 맑아지는 느낌이었다면 막혀 있던 일에 번뜩이는 해법이 떠오른다는 뜻으로 해석된다. 주변 사람들이 놀라며 바라보았다면 그 생각이 널리 인정받아 명예가 높아진다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-115","preview":"하는 일에 큰 반향이 일어나 판이 바뀌는 꿈","description":"옷에 불이 붙는 꿈은 자신을 드러내는 겉모습에 강한 기운이 옮겨붙어 하는 일의 흐름이 달라지는 것을 상징한다. 옷은 사회적 역할과 체면을 뜻하고 불은 번지는 기세를 뜻해, 둘이 만나는 장면이 일에서 큰 변화가 일어나는 것으로 풀이된다. 옷에서 번진 불빛이 주위를 환하게 밝혔다면 하는 일이 사람들의 눈에 띄며 크게 풀린다는 뜻으로 해석된다. 다만 뜨거움에 괴로워했다면 일이 뜻밖의 방향으로 번져 곤란을 겪을 수 있으니 서두르지 말라는 뜻으로 본다.","tags":["조건부"],"is_lucky":"conditional","luck_index":50},
{"id":"crawled-116","preview":"많은 사람의 주목 속에 인정받게 되는 길몽","description":"까만 밤하늘에 불꽃놀이를 하는 꿈은 어둠 속에서 자신의 존재가 환하게 드러나는 것을 상징한다. 밤은 아직 알려지지 않은 시기를, 불꽃은 순간 크게 피어나는 성취를 뜻해, 그동안 해 온 일이 마침내 빛을 보게 되는 조짐으로 풀이된다. 직접 불꽃을 쏘아 올렸다면 스스로 기획한 일이 성공해 그 공을 온전히 평가받는다는 뜻으로 해석된다. 불꽃이 연달아 하늘을 가득 채웠다면 좋은 소식이 잇따라 들려온다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-117","preview":"물의 상태에 따라 귀인과 근심이 갈리는 꿈","description":"물에 빠지는 꿈은 어떤 흐름이나 환경 속에 온몸으로 깊이 들어가게 되는 것을 상징한다. 물은 감정과 재물, 인연을 함께 뜻해, 그 속에 잠긴다는 것은 새로운 자리나 관계에 깊이 얽히게 된다는 의미로 풀이된다. 물속에서 숨이 편안하고 몸이 가벼웠다면 새 환경에 잘 적응해 도움을 줄 사람을 만난다는 뜻으로 해석된다. 다만 물이 탁하고 숨이 막혔다면 건강이나 형편에 걱정거리가 생길 수 있으니 몸을 돌보라는 뜻으로 본다.","tags":["조건부"],"is_lucky":"conditional","luck_index":50},
{"id":"crawled-118","preview":"들어온 물의 빛깔에 따라 살림의 운이 갈리는 꿈","description":"집안에 물이 차오르는 꿈은 바깥의 기운이 살림 안으로 밀려 들어오는 것을 상징한다. 물은 재물과 생활의 흐름을 뜻해, 그것이 집 안을 채운다는 것은 가정의 형편과 분위기가 크게 바뀐다는 의미로 풀이된다. 차오른 물이 고요하고 가족이 그 곁에 편안히 모여 있었다면 살림이 넉넉해지고 집안이 화목해진다는 뜻으로 해석된다. 다만 물에서 악취가 나고 탁했다면 집안에 우환이나 병치레가 생길 수 있으니 미리 살피라는 뜻으로 본다.","tags":["조건부"],"is_lucky":"conditional","luck_index":50},
{"id":"crawled-119","preview":"들고 나는 재물의 폭이 크게 출렁이는 꿈","description":"물이 불어나는 꿈은 주변의 기운이 빠르게 모여 삶의 판이 넓어지는 것을 상징한다. 물은 재물과 명예가 흘러드는 길로 여겨져, 그 물이 늘어난다는 것은 다루게 될 일과 돈의 크기가 달라진다는 의미로 풀이된다. 불어난 물이 잔잔하게 들판을 적셨다면 이름과 수입이 함께 오른다는 뜻으로 해석된다. 다만 흙탕물이 거세게 휩쓸었다면 쌓아 온 것을 잃을 수 있으니 무리한 확장을 피하라는 뜻으로 본다.","tags":["조건부"],"is_lucky":"conditional","luck_index":50},
{"id":"crawled-120","preview":"재산이 늘고 든든한 조력자를 만나는 길몽","description":"물고기를 많이 잡는 꿈은 노력한 만큼 거두어들이는 풍성한 결실을 상징한다. 물고기는 재물과 명예를 뜻하는 대표적인 상징으로, 그물 가득 물고기를 건져 올리는 장면이 손에 쥐는 몫이 커지는 조짐으로 풀이된다. 잡은 물고기가 크고 힘이 좋았다면 큰 거래나 계약이 성사되어 목돈을 쥐게 된다는 뜻으로 해석된다. 다른 사람과 함께 그물을 끌어 올렸다면 믿을 만한 동료의 도움으로 일이 더 커진다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-121","preview":"권력과 재물, 명예가 함께 따르는 길몽","description":"호랑이가 나오는 꿈은 강한 힘을 지닌 존재가 삶에 들어와 든든한 뒷배가 되는 것을 상징한다. 호랑이는 산의 왕으로 여겨져 높은 지위와 권세를 뜻하므로, 그 모습을 보는 것 자체가 큰 운을 만날 징조로 풀이된다. 호랑이의 털빛에 윤기가 흐르고 위엄이 있었다면 그만큼 운의 크기도 크다는 뜻이며, 태몽이라면 씩씩한 아이를 얻는다는 뜻으로 해석된다. 다만 호랑이가 지저분하고 병들어 보였다면 기회를 놓치거나 운이 기울 수 있으니 조심하라는 뜻으로 본다.","tags":["조건부","길몽","태몽"],"is_lucky":"lucky","luck_index":75},
{"id":"crawled-122","preview":"권세와 재물이 함께 손에 들어오는 길몽","description":"호랑이를 만지는 꿈은 쉽게 다가갈 수 없던 큰 힘을 자기 것으로 끌어당기는 것을 상징한다. 호랑이는 권력과 명예, 금전을 뜻하는데, 그 몸을 손으로 쓰다듬는다는 것은 그 기운과 직접 맞닿아 하는 일이 크게 성공하는 조짐으로 풀이된다. 호랑이가 순하게 몸을 맡겼다면 윗사람이나 유력한 사람의 신임을 얻어 중요한 자리를 맡게 된다는 뜻으로 해석된다. 털이 부드럽고 윤기가 흘렀다면 뜻밖의 돈이 생겨 살림이 넉넉해진다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-123","preview":"평범하던 삶에 생기와 재물이 깃드는 길몽","description":"하찮은 물건이 갑자기 용으로 변하는 꿈은 눈여겨보지 않던 것에서 큰 가능성이 깨어나는 것을 상징한다. 용은 입신출세와 명예, 신령한 힘을 뜻해, 흔한 물건이 용이 되는 것은 별 볼 일 없던 처지가 단번에 바뀌는 조짐으로 풀이된다. 변한 용이 하늘로 솟아올랐다면 오래 묵혀 둔 재능이나 계획이 뒤늦게 빛을 보며 이름을 얻는다는 뜻으로 해석된다. 용이 된 물건이 자신이 아끼던 것이었다면 곁에 있던 사람이나 인연에서 뜻밖의 복이 찾아온다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-124","preview":"재물과 기세가 꺾일 수 있음을 알리는 흉몽","description":"죽어 있는 용을 보는 꿈은 크게 일어나던 기운이 힘을 잃고 멈추는 것을 상징한다. 용은 명예와 권력, 재물을 뜻하는 존재라 그 용이 숨을 거둔 모습은 사업이나 지위를 받치던 힘이 사라지는 것으로 풀이된다. 죽은 용 앞에서 슬픔이 북받쳤다면 의지하던 사람이나 일에서 손을 떼게 되어 돈이 빠져나갈 수 있으니 큰 지출을 삼가라는 경고로 풀이된다. 태몽으로 이 꿈을 꾸었다면 아이와 산모의 건강을 각별히 살피라는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-125","preview":"큰 인물이나 귀한 인연을 맞이하는 길몽","description":"용이 몸에 와서 감기는 꿈은 크고 귀한 기운이 자신에게 단단히 깃드는 것을 상징한다. 용은 출세와 큰 세력을 뜻하는데, 그 용이 몸을 휘감는 것은 그 기운을 떼어 놓을 수 없을 만큼 가까이 품게 된다는 의미로 풀이된다. 태몽으로 꾸었다면 장차 크게 될 아이를 얻는다는 뜻으로, 미혼이라면 앞날이 밝은 사람과 짝을 맺는다는 뜻으로 해석된다. 용이 감긴 채로 편안하게 머물렀다면 예상하지 못한 재물이나 든든한 세력을 오래 지니게 된다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-126","preview":"귀인과 손잡고 능력을 펼칠 기회를 얻는 길몽","description":"용을 꼭 껴안는 꿈은 손이 닿지 않을 것 같던 큰 기운을 품 안에 들이는 것을 상징한다. 용은 입신출세와 명예, 신령한 힘을 뜻해, 그 용을 끌어안는 것은 평소 가까이하기 어려운 훌륭한 사람과 함께하게 되는 조짐으로 풀이된다. 용이 놀라지 않고 품에 가만히 안겼다면 윗사람의 신뢰를 얻어 중요한 일을 맡게 된다는 뜻으로 해석된다. 껴안은 용의 몸이 따뜻하게 느껴졌다면 함께 일하는 사람들과의 관계가 두터워져 성과가 오래 이어진다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-127","preview":"높은 자리에 올라 큰 뜻을 펼치게 되는 길몽","description":"용을 타고 하늘을 나는 꿈은 거침없는 기세로 까마득한 곳까지 오르는 출세를 상징한다. 용은 입신출세를, 하늘은 가장 높은 지위를 뜻해, 그 둘을 함께 누비는 장면이 많은 사람을 이끄는 위치에 서는 조짐으로 풀이된다. 아래로 넓은 땅과 사람들이 내려다보였다면 맡게 될 일의 규모가 크고 영향력이 넓게 미친다는 뜻으로 해석된다. 태몽이라면 훌륭한 인물로 자랄 아이가 태어난다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-128","preview":"마음 맞는 동반자와 함께 크게 성공하는 길몽","description":"용 두 마리가 서로 엉기어 하늘로 오르는 꿈은 두 힘이 하나로 합쳐져 더 높이 나아가는 것을 상징한다. 용은 출세와 번영을 뜻하는데, 두 마리가 함께 솟아오르는 모습은 혼자일 때보다 손을 맞잡을 때 일이 더 크게 풀린다는 의미로 풀이된다. 두 용이 다투지 않고 나란히 날아올랐다면 동업이나 협력이 순조롭게 이어져 큰 결실을 맺는다는 뜻으로 해석된다. 미혼이라면 서로 힘이 되어 줄 짝을 만나 함께 앞날을 일궈 간다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-129","preview":"집안에 영광이 깃들고 가문이 일어나는 길몽","description":"하늘을 날던 용이 집 안으로 날아 들어오는 꿈은 먼 곳의 큰 복이 자신의 집으로 찾아드는 것을 상징한다. 용은 입신출세와 명예를 뜻하고 집은 가족과 혈통을 뜻해, 용이 집에 머무르는 것은 집안 전체의 위상이 높아지는 조짐으로 풀이된다. 용이 집 안에 자리를 잡고 오래 머물렀다면 가족 가운데 누군가가 이름을 떨쳐 그 명성이 대를 이어 간다는 뜻으로 해석된다. 태몽이라면 집안을 크게 일으킬 귀한 아이가 태어난다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-130","preview":"잘나가던 권세나 사업이 기울 수 있는 흉몽","description":"하늘에서 용이 떨어져 죽는 꿈은 정점에 있던 기세가 한순간에 꺾이는 것을 상징한다. 용은 권력과 큰 사업을 뜻하고 하늘은 그 기세가 가장 높은 곳을 뜻해, 그곳에서 추락하는 것은 쌓아 올린 지위가 무너지는 조짐으로 풀이된다. 떨어진 용이 자신의 발밑에 쓰러졌다면 자신이 몸담은 조직이나 윗사람의 몰락에 휘말려 손해를 볼 수 있으니 조심하라는 경고로 풀이된다. 멀리서 떨어지는 모습을 지켜보기만 했다면 큰 위기의 소식을 듣게 되더라도 직접적인 피해는 비켜 간다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-131","preview":"큰 성공으로 이름을 널리 떨치게 되는 길몽","description":"용이 하늘을 날며 큰 소리를 내는 꿈은 자신의 존재가 세상에 크게 알려지는 것을 상징한다. 용은 입신출세와 명예를 뜻하고 그 울음소리는 멀리 퍼져 나가는 명성을 뜻해, 하는 일이 크게 이루어져 많은 사람의 존경을 받는 조짐으로 풀이된다. 용의 소리가 맑고 우렁차게 울려 퍼졌다면 좋은 평판이 빠르게 퍼져 뜻밖의 기회가 잇따른다는 뜻으로 해석된다. 그 소리를 듣고 사람들이 모여들었다면 자신을 따르고 돕는 사람이 많아진다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-132","preview":"뜻밖의 재난으로 권세와 재산을 잃을 수 있는 흉몽","description":"용이 자신을 죽이는 꿈은 거스를 수 없는 큰 힘에 짓눌려 자신의 자리를 내주는 것을 상징한다. 용은 권력과 세도를 뜻하는 존재라, 그 용에게 해를 입는 것은 힘 있는 상대의 뜻에 휘말려 피해를 보는 상황으로 풀이된다. 용에게 쫓기다 끝내 붙잡혔다면 피하려던 분쟁이나 다툼에 결국 얽히게 될 수 있으니 계약과 보증을 각별히 조심하라는 경고로 풀이된다. 죽음의 순간에 두려움보다 담담함이 컸다면 큰 손실을 겪은 뒤 오히려 새 출발의 계기를 얻는다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-133","preview":"아직은 때를 기다리며 힘을 길러야 함을 알리는 꿈","description":"연못 속에서 잠든 용을 보는 꿈은 큰 뜻과 능력이 아직 깨어나지 않은 채 안에 머물러 있는 것을 상징한다. 용은 출세와 명예를 뜻하지만 연못은 하늘로 오르기 전 머무는 자리를 뜻해, 지금은 뜻을 펼칠 시기가 무르익지 않았다는 의미로 풀이된다. 용이 잠결에 몸을 뒤척이거나 눈을 떴다면 바라던 때가 머지않아 찾아온다는 뜻으로 해석된다. 잠든 용을 깨우려다 그만두었다면 서두르기보다 실력을 쌓으며 기회를 노리는 편이 낫다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-134","preview":"능력에 버거운 일을 떠안게 될 수 있는 흉몽","description":"용이 나무에 걸려 있는 꿈은 큰 뜻을 품고도 제 힘을 펼치지 못한 채 묶여 있는 처지를 상징한다. 하늘을 날아야 할 용이 나뭇가지에 붙들린 모습은 자신의 역량을 넘어서는 일을 맡아 옴짝달싹 못 하게 되는 상황으로 풀이된다. 용이 벗어나려고 몸부림칠수록 더 얽혀 들었다면 욕심을 부릴수록 일이 꼬이고 손해가 커질 수 있으니 조심하라는 경고로 풀이된다. 누군가 나무 아래에서 용을 추켜세우며 부추겼다면 주변의 달콤한 말에 넘어가 무리한 결정을 내리지 말라는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-135","preview":"권세 있는 사람의 도움으로 일이 풀리는 길몽","description":"용이 입에서 불을 뿜어 그 열기에 뜨거워하는 꿈은 강한 힘이 가까이에서 자신에게 미치는 것을 상징한다. 용은 높은 지위와 신령한 힘을 뜻하고 불은 그 힘이 바깥으로 뻗어 나가는 기운을 뜻해, 그 열기를 받는 것은 영향력 있는 이의 힘이 자신의 일에 닿는 조짐으로 풀이된다. 뜨거웠지만 다치지 않고 견뎌 냈다면 처음에는 부담스러운 요구가 있어도 결국 그 덕분에 일을 무사히 마무리한다는 뜻으로 해석된다. 불길이 앞을 가로막던 것을 태워 없앴다면 오래 막혀 있던 문제가 단번에 해결된다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-136","preview":"새로운 생각으로 낡은 틀을 깨뜨리는 길몽","description":"용의 꼬리가 산봉우리를 자르는 꿈은 거대한 힘이 오래 버텨 온 것을 단번에 허무는 것을 상징한다. 용은 큰 인물이나 그의 사상과 영향력을 뜻하고 산봉우리는 굳게 자리 잡은 기존의 학문이나 관행을 뜻해, 그것이 잘려 나가는 것은 새로운 흐름이 옛 질서를 넘어서는 조짐으로 풀이된다. 잘린 봉우리 너머로 새 길이 열리는 것을 보았다면 자신의 연구나 제안이 인정받아 다음 단계로 나아가는 계기가 된다는 뜻으로 해석된다. 그 장면을 곁에서 지켜보며 감탄했다면 뛰어난 인물을 만나 그 사상에 크게 영향을 받게 된다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-137","preview":"귀한 것을 업신여겨 시비와 망신을 부르는 흉몽","description":"용의 얼굴에 침을 뱉는 꿈은 마땅히 존중해야 할 대상을 함부로 대하는 태도를 상징한다. 용은 높은 권위와 신성함을 뜻해, 그 얼굴을 더럽히는 행동은 스스로 화를 불러들이는 경솔함으로 풀이된다. 침을 뱉은 뒤 용이 노려보았다면 윗사람이나 힘 있는 사람과 부딪혀 다툼이나 소송에 얽힐 수 있으니 말과 행동을 조심하라는 경고로 풀이된다. 곧바로 뉘우치며 용에게 고개를 숙였다면 실수를 빨리 바로잡아 큰 창피는 피한다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-138","preview":"명예와 신분이 크게 오르는 출세의 길몽","description":"임금이 앉던 용상에 앉는 꿈은 가장 높은 자리와 권위를 자신이 차지하게 되는 것을 상징한다. 용상은 최고의 지위와 행운을 뜻하는 자리라, 그곳에 앉는 것은 시험 합격이나 요직 진출처럼 나라 안에서 인정받는 조짐으로 풀이된다. 용상에 앉은 자신에게 많은 사람이 고개를 숙였다면 이끄는 자리에 올라 사람들의 신망을 얻는다는 뜻으로 해석된다. 앉은 자리가 편안하고 몸에 꼭 맞았다면 그 지위를 오래 지키며 이름을 이어 간다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"crawled-139","preview":"지위와 명예가 물러날 수 있음을 알리는 흉몽","description":"용상에서 내려오는 꿈은 누리던 최고의 자리와 권위를 내려놓게 되는 것을 상징한다. 용상은 가장 높은 지위와 행운을 뜻하는 자리라, 그곳을 떠나는 것은 맡고 있던 역할이 끝나거나 명성이 빛을 잃는 조짐으로 풀이된다. 용상을 떠나 계단을 밟다가 발을 헛디뎠다면 물러나는 과정에서 체면이 깎이거나 손해를 볼 수 있으니 조심하라는 경고로 풀이된다. 자리를 비운 뒤 마음이 오히려 홀가분했다면 무거운 책임을 덜고 새로운 길을 준비하게 된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"daily-001","preview":null,"description":"낡은 집을 고치고 수리하는 꿈은 삶의 터전을 스스로 가다듬어 새롭게 다지는 것을 상징한다. 집은 생활과 가족의 기반을 뜻해, 그것을 손보는 행위는 흐트러진 일상을 바로잡고 앞으로의 안정과 발전을 준비하는 조짐으로 풀이된다. 벽에 새 칠을 하고 집 안이 환해졌다면 집안 분위기가 밝아지고 가족 사이도 한결 화목해진다는 뜻으로 해석된다. 가족이 함께 팔을 걷어붙이고 수리를 도왔다면 서로 힘을 모아 미뤄 둔 일을 순조롭게 해낸다는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"daily-011","preview":null,"description":"금비녀가 유난히 눈부시게 빛나는 꿈은 겉으로 드러나는 화려함에 마음이 쏠리는 것을 상징한다. 비녀는 예로부터 혼인과 집안 여성의 품위를 뜻했는데, 그것이 지나치게 번쩍이는 모습은 화려함 뒤에 가려진 허점을 일깨우는 것으로 풀이된다. 빛나는 비녀를 손에 쥐려다 떨어뜨렸다면 욕심을 부리다 가까운 사람과의 관계가 틀어질 수 있으니 조심하라는 경고로 풀이된다. 다른 사람의 머리에 꽂힌 비녀가 빛났다면 남의 형편을 부러워하다 자신의 살림을 소홀히 하게 된다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"daily-021","preview":null,"description":"타야 할 기차나 버스를 놓치는 꿈은 현실에서 때를 맞추지 못해 아쉬움이 남는 상황을 상징한다. 정해진 시각에 떠나는 탈것은 한 번 지나가면 되돌릴 수 없는 시기와 흐름을 뜻해, 이를 놓치는 장면이 결정을 미루는 마음과 이어져 풀이된다. 떠나는 차를 쫓아 달리다 넘어졌다면 서두르다 일을 그르쳐 손해를 볼 수 있으니 침착하게 준비하라는 경고로 풀이된다. 놓쳤는데도 마음이 담담했거나 곧 다음 차를 탔다면 기다리던 때가 다시 온다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"daily-030","preview":null,"description":"자신의 것이 아닌 남의 옷을 입고 있는 꿈은 본래의 자리에서 벗어나 낯선 역할을 떠맡는 것을 상징한다. 옷은 그 사람의 처지와 신분을 뜻해, 남의 옷을 걸치는 것은 자신에게 맞지 않는 책임이나 상황을 떠안게 되는 조짐으로 풀이된다. 옷이 너무 커서 끌리거나 단추가 채워지지 않았다면 감당하기 벅찬 일을 맡아 손해가 따를 수 있으니 무리한 약속을 피하라는 뜻이다. 그 옷의 주인이 나타나 옷을 돌려 달라고 했다면 남의 일에 끼어들었다가 구설에 오른다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"nature-007","preview":null,"description":"비 갠 하늘에 무지개가 걸리는 꿈은 어려운 시기가 지나고 좋은 소식이 이어지는 것을 상징한다. 무지개는 하늘과 땅을 잇는 다리처럼 여겨져, 끊겼던 인연이나 기다리던 소식이 이어진다는 의미로 풀이된다. 무지개를 타고 오르는 꿈이라면 출세나 명예를 얻는다는 뜻으로 더욱 좋게 해석된다. 무지개가 금세 흐려지며 사라졌다면 좋은 일이 짧게 스쳐 갈 수 있으니 기회가 왔을 때 바로 붙잡으라는 뜻으로 본다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"nature-025","preview":null,"description":"우물가에 뽕나무가 자라는 꿈은 맑게 유지되어야 할 곳에 어울리지 않는 것이 뿌리내리는 상황을 상징한다. 우물은 집안의 살림과 생명의 근원을 뜻하는데, 그 곁에 낯선 나무가 자라는 것은 생활의 흐름이 조금씩 어긋나고 있다는 의미로 풀이된다. 뽕나무 뿌리가 우물 안까지 파고들어 물이 흐려졌다면 집안의 재물이나 건강에 우환이 스며들 수 있으니 작은 문제부터 살피라는 경고로 풀이된다. 뽕나무를 뽑아내고 우물가를 정리했다면 걱정의 씨앗을 일찍 걷어 내어 큰 탈 없이 지나간다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null},
{"id":"unlucky-025","preview":null,"description":"검은 그림자가 계속 뒤따라오는 꿈은 실체 없이 마음을 짓누르는 걱정거리를 상징한다. 그림자는 해결되지 않은 채 미뤄 둔 일이나 드러나지 않은 두려움을 뜻해, 그것이 떨어지지 않고 따라붙는 모습은 마음속 근심이 점점 커지고 있다는 의미로 풀이된다. 그림자가 점점 가까워져 숨이 가빠졌다면 쌓인 스트레스가 건강을 해칠 수 있으니 무리하지 말라는 경고로 풀이된다. 밝은 곳으로 나서자 그림자가 옅어졌다면 믿을 만한 사람에게 고민을 털어놓으면 걱정이 한결 가벼워진다는 뜻으로 해석된다.","tags":null,"is_lucky":null,"luck_index":null}
]
$data$;
  n int;
begin
  -- 1) 대상 행이 전부 있는지 확인 — 하나라도 없으면 전체 취소
  select count(*) into n
  from public.dream_items d
  join jsonb_to_recordset(src) as e(id text) using (id);
  if n <> 157 then
    raise exception '대상 행 % 건 — 157 건이어야 합니다. 적용을 취소합니다.', n;
  end if;

  -- 2) 현재 값 백업 — PostgREST 에 노출되지 않는 backup 스키마에 둔다.
  create schema if not exists backup;
  create table if not exists backup.dream_items_0019 (
    id           text primary key,
    preview      text,
    description  text,
    tags         text[],
    is_lucky     text,
    luck_index   integer,
    backed_up_at timestamptz not null default now()
  );
  insert into backup.dream_items_0019 (id, preview, description, tags, is_lucky, luck_index)
  select d.id, d.preview, d.description, d.tags, d.is_lucky, d.luck_index
  from public.dream_items d
  join jsonb_to_recordset(src) as e(id text) using (id)
  on conflict (id) do nothing;

  -- 3) 반영
  update public.dream_items d
  set preview     = coalesce(e.preview, d.preview),
      description = e.description,
      tags        = coalesce(e.tags, d.tags),
      is_lucky    = coalesce(e.is_lucky, d.is_lucky),
      luck_index  = coalesce(e.luck_index, d.luck_index)
  from jsonb_to_recordset(src) as e(id text, preview text, description text, tags text[], is_lucky text, luck_index integer)
  where d.id = e.id;

  -- 4) 결과 확인 — 본문이 전부 새 값인지
  select count(*) into n
  from public.dream_items d
  join jsonb_to_recordset(src) as e(id text, description text) using (id)
  where d.description = e.description;
  if n <> 157 then
    raise exception '반영 확인 실패: % / 157 건. 적용을 취소합니다.', n;
  end if;

  raise notice '0019 적용 완료: % 건', n;
end
$mig$;
